INSERT INTO public.devotional_content (id, activity_id, bible_text, bible_reference, reflection, prayer, practice, questions, created_at, updated_at, lesson_id, day_number, title, worship_song_id, church_id)
VALUES
('4dbb85d5-3f7b-45b6-9cec-ea60b675403a', NULL, 'Pois todos pecaram e carecem da glória de Deus.', 'Romanos 3:23', 'O Evangelho começa com uma notícia difícil: todos pecamos. Não existe exceção. Reconhecer isso é o primeiro passo para a graça.', 'Senhor, reconheço que sou pecador e preciso de Ti. Amém.', 'Reflita honestamente sobre áreas de pecado em sua vida.', '{"O que é pecado segundo a Bíblia?","Por que é difícil admitir que somos pecadores?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 1, 'O problema: o pecado', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('77309ff9-1580-4399-adda-39f9607172e7', NULL, 'As vossas iniquidades fazem separação entre vós e o vosso Deus.', 'Isaías 59:2', 'O pecado nos separa de Deus. Não é que Ele se afastou — nós nos afastamos. A consequência é real e séria.', 'Pai, não quero viver separado de Ti. Aproxima-me. Amém.', 'Ore pedindo sensibilidade para perceber quando o pecado te afasta de Deus.', '{"Como o pecado nos separa de Deus?","Você já sentiu essa separação?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 2, 'A consequência: separação', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('88d856c5-0668-4ce6-9255-2de80163306b', NULL, 'Mas Deus prova o seu próprio amor para conosco pelo fato de ter Cristo morrido por nós, sendo nós ainda pecadores.', 'Romanos 5:8', 'A graça é isso: Deus agiu primeiro, enquanto ainda estávamos perdidos. Não precisamos nos "arrumar" antes de vir a Ele.', 'Obrigado, Deus, pela graça que me alcançou antes de eu merecer. Amém.', 'Agradeça a Deus pela Sua iniciativa de amor.', '{"O que é graça?","Como a graça é diferente de mérito?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 3, 'A graça: Deus toma a iniciativa', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('930670e0-ddc5-44ee-bb5e-b256200ae343', NULL, 'Ele foi traspassado pelas nossas transgressões e moído pelas nossas iniquidades.', 'Isaías 53:5', 'Na cruz, Jesus levou sobre si o nosso pecado. O preço da nossa liberdade foi altíssimo — e Ele pagou voluntariamente.', 'Jesus, obrigado por pagar o preço na cruz por mim. Amém.', 'Medite na cruz e agradeça pelo sacrifício de Jesus.', '{"O que aconteceu na cruz?","Como o sacrifício de Jesus te impacta pessoalmente?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 4, 'A cruz: o preço pago', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b42bfa7c-7413-44c7-9895-bbb77b648138', NULL, 'Cristo morreu pelos nossos pecados, foi sepultado e ressuscitou ao terceiro dia.', '1 Coríntios 15:3-4', 'O Evangelho não termina na cruz. A ressurreição é a prova de que o sacrifício foi aceito e a morte foi vencida!', 'Jesus vivo, minha esperança é porque Tu ressuscitaste! Amém.', 'Celebre a vitória de Cristo — cante, dance ou escreva sobre a ressurreição.', '{"Por que a ressurreição é essencial ao Evangelho?","O que mudaria se Jesus não tivesse ressuscitado?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 5, 'A ressurreição: vitória sobre a morte', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('85d81bab-bf88-4fbd-a492-6f425e281f47', NULL, 'Pela graça sois salvos, mediante a fé; e isto não vem de vós; é dom de Deus.', 'Efésios 2:8-9', 'A fé é a mão que recebe o presente da graça. Não é obra nossa — até a fé é dom de Deus.', 'Senhor, aumenta minha fé. Recebo Tua graça de coração aberto. Amém.', 'Leia Efésios 2:8-9 em voz alta e personalize: "Pela graça EU sou salvo."', '{"O que é fé segundo a Bíblia?","Fé é sentimento ou decisão?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 6, 'A resposta: fé', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('200a0b3b-87b4-4874-a4d4-98f14cad3917', NULL, 'Se alguém está em Cristo, é nova criatura.', '2 Coríntios 5:17', 'O Evangelho não é só perdão — é transformação. Quem crê se torna nova criatura. A mudança começa de dentro.', 'Deus, transforma-me. Faça-me novo de dentro para fora. Amém.', 'Identifique algo que mudou em você desde que conheceu o Evangelho.', '{"O que significa ser nova criatura?","Que mudanças você já percebe?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 7, 'O Evangelho transforma', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('c5e3aaa2-eba4-49fb-a24c-8f7f59038326', NULL, 'Porque não me envergonho do evangelho, pois é o poder de Deus para a salvação de todo aquele que crê.', 'Romanos 1:16', 'O Evangelho não é exclusivo — é para toda pessoa, em toda cultura, em todo tempo. Ninguém está fora do alcance de Deus.', 'Pai, obrigado por um Evangelho que alcança todos. Amém.', 'Ore por alguém que ainda não conhece o Evangelho.', '{"Por que Paulo diz que não se envergonha do Evangelho?","Você tem vergonha de falar sobre Jesus?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 8, 'O Evangelho é para todos', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('72f15fe8-b169-47a4-864e-ed2b768d896e', NULL, 'Já não sou eu quem vive, mas Cristo vive em mim.', 'Gálatas 2:20', 'O Evangelho não é só crido — é vivido. Cristo vive em nós e através de nós. Nossa vida é a mensagem.', 'Cristo, vive em mim e através de mim hoje. Amém.', 'Viva hoje consciente de que Cristo habita em você.', '{"O que significa Cristo viver em você?","Como isso muda suas atitudes hoje?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 9, 'Viver o Evangelho', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('4ffd0b1f-91c0-4283-9989-dc1be0d6e87d', NULL, 'Porque Deus amou o mundo de tal maneira que deu o seu Filho unigênito.', 'João 3:16', 'O Evangelho se resume assim: Deus amou, Deus deu, quem crê tem vida eterna. Simples, profundo, transformador.', 'Pai, obrigado pelo Evangelho. Que eu nunca perca o encanto dessa verdade. Amém.', 'Escreva o Evangelho em suas palavras para se preparar para o encontro.', '{"Como você explicaria o Evangelho em uma frase?","O que mais te impactou nessas duas semanas?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', 'd269baf3-5996-4b2a-8778-e1a3c748cbfd', 10, 'Resumo: o coração do Evangelho', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('95a7b6fb-c26b-409c-b35b-7be31c00fbca', NULL, 'Tendo nEle também crido, fostes selados com o Espírito Santo da promessa.', 'Efésios 1:13-14', 'A salvação não depende de nós — somos selados pelo Espírito Santo. É a garantia de Deus, não a nossa.', 'Pai, obrigado pelo selo do Espírito que garante minha salvação. Amém.', 'Reflita sobre a segurança que vem de saber que Deus sela Seus filhos.', '{"O que significa ser selado pelo Espírito?","Isso te dá segurança?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 1, 'Salvação: obra de Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('058e20af-9765-464c-90b2-f825438c87fa', NULL, 'Justificados pela fé, temos paz com Deus.', 'Romanos 5:1', 'Ser justificado significa ser declarado justo por Deus — não por mérito, mas pela fé em Cristo. Isso traz paz real.', 'Senhor, obrigado por me declarar justo pela fé. Descanso em Ti. Amém.', 'Medite na paz que vem da justificação. Você está em paz com Deus.', '{"O que é justificação?","Como ela é diferente de ser \"uma boa pessoa\"?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 2, 'Justificação pela fé', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('47a72815-5bc5-4bed-ae2a-245b97039b89', NULL, 'Nada poderá separar-nos do amor de Deus que está em Cristo Jesus.', 'Romanos 8:38-39', 'Nem morte, nem vida, nem anjos, nem poderes... NADA pode nos separar do amor de Deus. Essa é a certeza.', 'Deus, obrigado porque nada me separa do Teu amor. Amém.', 'Faça uma lista do que te causa medo e declare sobre cada item: "Isso não me separa de Deus."', '{"O que mais te dá medo de perder?","Como Romanos 8:38-39 responde a esse medo?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 3, 'Nada nos separa', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('bb34ee43-b4d6-4fe4-b667-b5b8c215f61d', NULL, 'Aquele que começou boa obra em vós há de completá-la.', 'Filipenses 1:6', 'Deus não abandona projetos pela metade. Ele que começou, vai completar. Sua fidelidade é maior que nossas falhas.', 'Senhor, confia em Ti para completar o que começaste em mim. Amém.', 'Lembre-se de que Deus é fiel mesmo quando você falha.', '{"Deus já abandonou algum de Seus projetos?","O que isso significa para sua vida?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 4, 'Ele completará a obra', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('ab5db71c-e093-4c5b-a2c5-878b061e261e', NULL, '“Criou Deus o homem à sua imagem, à imagem de Deus o criou; homem e mulher os criou.”', 'Gênesis 1.27', 'Antes de qualquer opinião, sentimento ou rótulo, existe uma verdade fundamental: você foi criado por Deus. Isso significa que sua vida tem valor, propósito e dignidade. Você não é um acidente. Você não precisa provar que é importante — você já é importante porque foi criado à imagem de Deus. O mundo pode tentar definir quem você é, mas Deus já declarou isso desde o começo.', 'Senhor, obrigado porque eu fui criado por Ti. Ajuda-me a lembrar disso quando eu me sentir inseguro. Amém.', 'Hoje, repita ao longo do dia: 👉 “Eu fui criado por Deus e tenho valor.”', '{"Você já pensou que foi criado à imagem de Deus?","O que muda quando você acredita nisso?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 1, 'QUEM EU SOU?', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('c60020e1-17b8-42ee-90a5-b273e67d4060', NULL, '“Enganoso é o coração, mais do que todas as coisas, e desesperadamente corrupto; quem o conhecerá?”', 'Jeremias 17.9', 'Hoje, muita gente diz: “Siga seu coração.” Mas a Bíblia mostra que nosso coração nem sempre é confiável. Nossos sentimentos mudam o tempo todo. Às vezes estamos bem, às vezes não. Se basearmos nossa identidade apenas no que sentimos, vamos viver confusos. Deus nos convida a confiar mais na verdade dEle do que nas emoções do momento.', 'Deus, ajuda-me a não viver apenas pelos meus sentimentos, mas pela Tua verdade. Amém.', 'Antes de tomar uma decisão hoje, pare e pergunte: 👉 “O que Deus diz sobre isso?”', '{"Você já tomou uma decisão só pelo que sentia?","O que aconteceu depois?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 2, 'O CORAÇÃO PODE ENGANAR', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('26d6ab1c-c2bd-4589-be1a-ca0437979f85', NULL, '“Então se abriram os olhos de ambos, e, percebendo que estavam nus, coseram folhas de figueira e fizeram para si aventais.”', 'Gênesis 3.7', 'Depois do pecado, algo mudou no coração humano. Adão e Eva sentiram vergonha. E isso continua acontecendo hoje. Muitas vezes sentimos vergonha de quem somos, insegurança, medo de não sermos aceitos. Isso mostra que algo foi quebrado dentro de nós. Mas essa não é o fim da história.', 'Senhor, quando eu me sentir inseguro, lembra-me que o Senhor não me abandonou. Amém.', 'Quando vier um pensamento de vergonha ou insegurança, lembre: 👉 “Deus não desistiu de mim.”', '{"Você já se sentiu inseguro ou com vergonha de quem é?","O que costuma causar isso em você?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 3, 'QUANDO TUDO QUEBRA', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('967f273e-4b87-4ab1-bb64-038c74103a7e', NULL, '“E assim, se alguém está em Cristo, é nova criatura; as coisas antigas já passaram; eis que se fizeram novas.”', '2 Coríntios 5.17', 'Em Jesus, nossa história não termina no pecado ou na confusão. Ele nos dá uma nova identidade. Isso não significa que tudo muda de um dia para o outro, mas significa que agora temos um novo começo. Em Cristo, você não é definido pelos seus erros, mas pela graça de Deus.', 'Jesus, obrigado porque o Senhor me dá uma nova vida. Ajuda-me a viver essa nova identidade. Amém.', 'Hoje, lembre-se: 👉 “Em Cristo, eu tenho um novo começo.”', '{"O que significa, para você, ser “nova criatura”?","Você já experimentou esse novo começo com Deus?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 4, 'NOVA IDENTIDADE', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('558abb17-2599-454d-b1e8-ff87e4c645b3', NULL, '“E o Verbo se fez carne e habitou entre nós, cheio de graça e de verdade.”', 'João 1.14', 'Jesus é cheio de graça e de verdade. Ele não ignora o pecado, mas também não rejeita as pessoas. Ele fala a verdade com amor. Isso é importante para nós também. Em um mundo cheio de opiniões, precisamos aprender a viver com esse equilíbrio: não abrir mão da verdade, mas também não perder o amor.', 'Senhor, ensina-me a viver com graça e verdade, como Jesus. Amém.', 'Hoje, escolha tratar alguém com mais graça e paciência.', '{"Você acha mais fácil falar a verdade ou demonstrar amor?","Como podemos viver com os dois juntos?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 5, 'GRAÇA E VERDADE', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('bbc842d3-1306-48ab-9479-71f3622752e7', NULL, '“Pois somos feitura dele, criados em Cristo Jesus para boas obras, as quais Deus de antemão preparou para que andássemos nelas.”', 'Efésios 2.10', 'Você não precisa inventar quem você é. Deus já te criou com propósito. Em Cristo, você descobre quem realmente é. Isso traz descanso. Você não precisa viver tentando impressionar os outros — você já pertence a Deus.', 'Senhor, ajuda-me a viver com segurança em quem o Senhor diz que eu sou. Amém.', 'Hoje, seja você mesmo diante de Deus.', '{"Você já tentou mudar quem é para agradar alguém?","Como isso fez você se sentir?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 6, 'NÃO PRECISO ME INVENTAR', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('d104e958-f58e-4301-b6bd-1687f3412384', NULL, '“Senhor, tu me sondas e me conheces.”', 'Salmo 139.1', 'Deus conhece tudo sobre você — até o que ninguém mais vê. E mesmo assim, Ele te ama. Isso é graça. Você não precisa esconder nada de Deus. Pode ser sincero, pode abrir o coração. Ele não se afasta de você — Ele se aproxima.', 'Deus, obrigado porque o Senhor me conhece e mesmo assim me ama. Amém.', 'Hoje, fale com Deus com sinceridade total.', '{"Você acha fácil ser sincero com Deus?","O que você costuma esconder?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 7, 'DEUS ME CONHECE', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('4162aaaa-3669-411b-920c-e6e4c0aaab1a', NULL, '“Confia no Senhor de todo o teu coração e não te estribes no teu próprio entendimento.”', 'Provérbios 3.5', 'Nem sempre o que sentimos mostra a verdade. Às vezes sentimos medo sem motivo, ou insegurança sem razão. Deus nos chama a confiar nEle acima dos nossos sentimentos. Isso não é ignorar o que sentimos, mas não deixar que isso controle nossa vida.', 'Senhor, ajuda-me a confiar em Ti mais do que nos meus sentimentos. Amém.', 'Quando surgir uma dúvida, diga: 👉 “Eu escolho confiar em Deus.”', '{"Você costuma confiar mais nos seus sentimentos ou em Deus?","Em que situações isso aparece?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 8, 'MAIS QUE SENTIMENTOS', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('409af145-f9fc-4295-b3ac-9824201aa681', NULL, '“Mas, a todos quantos o receberam, deu-lhes o poder de serem feitos filhos de Deus.”', 'João 1.12', 'Em Cristo, você não é apenas uma pessoa tentando acertar na vida. Você é filho de Deus. Isso muda tudo. Deus não te vê como alguém distante, mas como alguém amado, parte da família dEle. Sua identidade está nisso.', 'Pai, obrigado porque em Jesus eu sou Teu filho. Amém.', 'Hoje, lembre-se: 👉 “Eu sou filho de Deus.”', '{"Você se vê como filho de Deus?","O que isso muda na sua vida?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 9, 'FILHO DE DEUS', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('7612b1ac-7f17-44e1-9dd2-db428e0ed47e', NULL, '“Porque morrestes, e a vossa vida está oculta juntamente com Cristo, em Deus.”', 'Colossenses 3.3', 'Nossa vida está segura em Cristo. Isso significa que nossa identidade não depende do que os outros pensam, nem do que sentimos em um dia ruim. Está firme em Deus. E isso nos dá segurança para viver.', 'Senhor, firma minha identidade em Ti. Amém.', 'Repita hoje: 👉 “Minha identidade está em Cristo.”', '{"O que costuma abalar sua identidade?","Como você pode firmá-la mais em Cristo?"}', '2026-05-13 20:13:21.2081+00', '2026-05-13 20:13:21.2081+00', 'a988a6eb-6505-45b4-93b4-eb01f7940877', 10, 'IDENTIDADE FIRME', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('9c3a09fe-854f-4632-830f-b1088b81f8bc', NULL, '“No princípio, Deus criou os céus e a terra.”', 'Gênesis 1:1', 'Tudo na nossa vida tem um começo. Jogos começam. Séries começam. Nossa vida começou um dia. Mas Deus não. Antes de existir universo, tempo, estrelas ou pessoas, Deus já existia.\nIsso mostra algo muito importante: Deus não depende de nada. Nós dependemos de ar, comida, sono e amor. Mas Deus é eterno e poderoso.\nAo mesmo tempo, esse Deus tão grande decidiu criar o mundo e criar você. Isso significa que sua vida não é acidente. Você foi pensado por Deus.\nE mais incrível ainda: o Deus que criou o universo quer se relacionar com você.', '“Deus, obrigado porque o Senhor é eterno e poderoso. Obrigado porque minha vida não é um acidente. Ajuda-me a lembrar que fui criado por Ti e para Ti. Amém.”', 'Olhe para algo da criação hoje — céu, árvores, chuva, animais — e lembre-se: 👉 Deus criou tudo isso… e também criou você.', '{"Você já parou para pensar que Deus existia antes de tudo?","O que muda saber que sua vida foi criada por Deus?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 1, 'O DEUS QUE EXISTE ANTES DE TUDO', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('20090d4a-9694-41a4-b221-bfb700b37693', NULL, '“Senhor, tu me sondas e me conheces.”', 'Salmo 139:1', 'Às vezes parece que ninguém entende o que sentimos. Tem dias em que nos sentimos invisíveis, sozinhos ou incompreendidos.\nMas a Bíblia mostra que Deus conhece profundamente nossa vida. Ele conhece nossas alegrias, medos, dúvidas e até pensamentos.\nIsso pode assustar um pouco no começo. Mas também traz conforto. Porque significa que você nunca está sozinho.\nDeus não observa sua vida de longe. Ele está perto.\nE mesmo conhecendo seus erros, Ele continua amando você.', '“Senhor, obrigado porque Tu me conheces completamente. Ajuda-me a perceber Tua presença perto de mim todos os dias. Amém.”', 'Antes de dormir, conte para Deus como foi seu dia. Fale com sinceridade, como quem conversa com alguém próximo.', '{"Você costuma sentir que Deus está perto ou distante?","Como seria sua vida se você lembrasse mais da presença de Deus?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 2, 'DEUS NÃO ESTÁ DISTANTE', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('7e073a3a-cb53-4701-8c14-e040073e1334', NULL, '“Quem me vê, vê o Pai.”', 'João 14:9', 'Muita gente imagina Deus de maneiras erradas. Alguns pensam em um Deus bravo e distante. Outros imaginam alguém indiferente.\nMas Jesus veio mostrar quem Deus realmente é.\nQuando vemos Jesus acolhendo pessoas, perdoando pecadores e cuidando dos sofridos, vemos o coração do próprio Deus.\nJesus não veio apenas ensinar sobre Deus.\nEle veio revelar Deus.\nNa cruz, Jesus mostrou o maior amor possível: entregar a própria vida para nos salvar.', '“Jesus, obrigado porque através de Ti posso conhecer o coração do Pai. Ajuda-me a confiar mais no Teu amor. Amém.”', 'Leia um trecho dos Evangelhos hoje e observe como Jesus tratava as pessoas.', '{"Qual imagem de Deus você tinha antes?","O que mais chama sua atenção na vida de Jesus?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 3, 'JESUS MOSTRA QUEM DEUS É', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('54bc8ec7-9fa5-4011-b0c8-242e05d1c833', NULL, '“Aquele que é a Palavra tornou-se carne e viveu entre nós.”', 'João 1:14', 'O cristianismo é diferente porque fala de um Deus que entrou na história humana.\nJesus sentiu fome, tristeza, dor e rejeição. Ele viveu nossa realidade.\nIsso significa que Deus entende nossa dor de verdade.\nQuando você estiver triste, cansado ou com medo, lembre-se:\nJesus sabe exatamente o que é sofrer.\nE mesmo assim Ele venceu o pecado e a morte.', '“Jesus, obrigado porque Tu vieste até nós. Obrigado porque entendes minhas lutas e permaneces comigo. Amém.”', 'Quando estiver ansioso ou preocupado hoje, faça uma oração simples: “Jesus, caminha comigo.”', '{"Por que é importante saber que Jesus viveu como nós?","Em quais momentos você mais precisa lembrar que Deus entende sua dor?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 4, 'O DEUS QUE VEIO ATÉ NÓS', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('5642f8d4-dd1f-4dea-8fe0-b8d594be189a', NULL, '“Batizando-os em nome do Pai, do Filho e do Espírito Santo.”', 'Mateus 28:19', 'A Bíblia ensina que existe um só Deus, mas que Ele se revela em três pessoas: Pai, Filho e Espírito Santo.\nTalvez isso pareça difícil de entender completamente. E tudo bem. Deus é maior do que nossa mente consegue explicar totalmente.\nO Pai nos ama.\nO Filho nos salva.\nO Espírito Santo nos acompanha.\nA Trindade mostra que Deus é relacionamento, amor e comunhão desde sempre.\nE agora Deus nos convida a viver perto dEle.', '“Deus Pai, Filho e Espírito Santo, obrigado porque o Senhor se revelou a nós. Ajuda-me a crescer no conhecimento e no amor por Ti. Amém.”', 'Hoje, ao começar uma oração, lembre conscientemente que você está falando com o Deus Pai, Filho e Espírito Santo. Tente agradecer: ao Pai pelo cuidado, a Jesus pela salvação, e ao Espírito Santo pela presença diária. Depois, reflita: 👉 Deus não é distante. Ele está perto de você todos os dias.', '{"Qual pessoa da Trindade você entende melhor?","Como essa verdade ajuda você a conhecer mais Deus?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 5, 'UM SÓ DEUS', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('4152a0d3-710f-4417-a04d-57c10f02df96', NULL, '“Observem as aves do céu: não semeiam nem colhem nem armazenam em celeiros; contudo, o Pai celestial as alimenta.”', 'Mateus 6:26', 'Jesus queria mostrar que Deus não é um Pai ausente. Ele cuida da criação e também cuida de nós.\nIsso não significa que nunca teremos dificuldades. Mas significa que nunca estaremos abandonados.\nÀs vezes o medo do futuro toma conta do coração. Mas Deus continua sustentando nossa vida.\nSeu valor não depende de desempenho, aparência ou popularidade.\nVocê é amado porque pertence a Deus.', '“Pai, obrigado porque cuidas de mim mesmo quando estou preocupado. Ajuda-me a confiar mais no Teu cuidado. Amém.”', 'Entregue hoje uma preocupação específica para Deus em oração.', '{"O que mais costuma trazer preocupação para você?","Você consegue confiar seus medos a Deus?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 6, 'O PAI QUE CUIDA', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('962bfa9e-f272-4c46-bd96-6662efa16444', NULL, '“E eu pedirei ao Pai, e ele dará a vocês outro Conselheiro para estar com vocês para sempre.”', 'João 14:16', 'Jesus prometeu que não nos deixaria sozinhos.\nO Espírito Santo é Deus presente em nossa vida.\nEle consola, fortalece, ensina e guia.\nTalvez você nem sempre perceba, mas Deus continua agindo dentro do coração das pessoas.\nQuando sentimos paz em meio ao caos, coragem em meio ao medo ou vontade de buscar a Deus, o Espírito Santo está trabalhando.', '“Espírito Santo, obrigado porque não estou sozinho. Guia meus pensamentos, minhas palavras e minhas atitudes. Amém.”', 'Antes de começar suas atividades hoje, faça uma oração curta: 👉 “Espírito Santo, guia meu dia.”', '{"Você já percebeu Deus ajudando você em momentos difíceis?","O que significa saber que Deus está com você todos os dias?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 7, 'O ESPÍRITO SANTO ESTÁ COM VOCÊ', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('6ebe85d3-4e7e-4ba0-821b-f6dcdf481a56', NULL, '“Mas Deus demonstra seu amor por nós: Cristo morreu em nosso favor quando ainda éramos pecadores.”', 'Romanos 5:8', 'Muita gente acha que precisa merecer o amor de Deus sendo perfeita.\nMas a Bíblia mostra o contrário.\nJesus morreu por nós quando ainda éramos pecadores.\nIsso significa que o amor de Deus vem antes do nosso esforço.\nA salvação não é prêmio para pessoas boas.\nÉ presente de graça para quem confia em Cristo.\nIsso traz descanso ao coração.', '“Jesus, obrigado porque Teu amor não depende do meu desempenho. Ajuda-me a descansar na Tua graça. Amém.”', 'Quando errar hoje, em vez de fugir de Deus, aproxime-se dEle em oração.', '{"Você já sentiu que precisava “merecer” o amor de Deus?","O que muda saber que Deus ama você pela graça?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 8, 'O AMOR QUE NÃO PRECISA SER MERECIDO', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b81ef520-33b8-40d0-bef5-f2e56b81e44c', NULL, '“Porque somos criação de Deus realizada em Cristo Jesus para fazermos boas obras.”', 'Efésios 2:10', 'O mundo muitas vezes faz as pessoas acreditarem que não têm valor.\nMas Deus diz algo diferente:\nVocê foi criado por Ele.\nSua vida tem propósito.\nIsso não significa que você precisa ser perfeito ou famoso para ter valor. Seu valor vem do amor de Deus.\nEm Cristo, encontramos nossa verdadeira identidade.', '“Deus, obrigado porque minha vida tem valor em Ti. Ajuda-me a encontrar minha identidade em Cristo. Amém.”', 'Escreva em algum lugar: 👉 “Minha identidade está em Cristo.”', '{"O que normalmente faz as pessoas se sentirem valiosas hoje?","Onde você acha que sua identidade deve estar firmada?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 9, 'VOCÊ NÃO FOI CRIADO POR ACASO', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('58c6a731-f4a8-4c03-8cd3-d1eb558e7287', NULL, '“Esta é a vida eterna: que te conheçam, o único Deus verdadeiro, e a Jesus Cristo, a quem enviaste.”', 'João 17:3', 'Existe diferença entre saber sobre Deus e conhecer Deus.\nVocê pode saber muitas informações sobre alguém sem ter relacionamento com essa pessoa.\nConhecer Deus significa caminhar com Ele diariamente.\nSignifica confiar, conversar, ouvir Sua Palavra e permitir que Ele transforme nossa vida.\nA vida eterna começa quando passamos a viver com Deus.', '“Senhor, não quero apenas saber sobre Ti. Quero Te conhecer de verdade. Caminha comigo e fortalece minha fé. Amém.”', 'Separe alguns minutos hoje para ficar em silêncio e conversar sinceramente com Deus.', '{"Você sente que apenas sabe sobre Deus ou realmente está conhecendo Deus?","O que pode ajudar você a crescer nesse relacionamento?"}', '2026-05-14 00:04:01.279297+00', '2026-05-14 00:04:01.279297+00', 'f2e4513b-c426-4fc6-9aa5-ff282218a9ed', 10, 'CONHECER DEUS DE VERDADE', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('3f3730bc-1f02-4b80-8601-787ecb980eb4', NULL, 'Eu dou-lhes a vida eterna e jamais perecerão; ninguém as arrebatará da minha mão.', 'João 10:27-29', 'Jesus diz que Suas ovelhas estão seguras em Suas mãos. Ninguém pode nos arrancar de lá. Que promessa!', 'Pastor Jesus, estou seguro em Tuas mãos. Obrigado! Amém.', 'Descanse hoje na segurança de estar nas mãos de Jesus.', '{"O que significa estar nas mãos de Jesus?","Você se sente seguro nEle?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 5, 'Ovelhas seguras', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b8c05f92-2a22-48ea-b3c9-b0e87e5c74e4', NULL, 'Escrevi estas coisas para que saibais que tendes a vida eterna.', '1 João 5:13', 'Ter certeza da salvação não é arrogância — é fé na promessa de Deus. João escreveu para que soubéssemos!', 'Senhor, creio na Tua Palavra e sei que tenho vida eterna. Amém.', 'Leia 1 João 5:13 e afirme: "Eu SEI que tenho vida eterna."', '{"Por que alguns cristãos vivem em dúvida?","Como podemos ter certeza sem arrogância?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 6, 'Certeza ≠ arrogância', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('ec35c36a-037f-405f-b365-f70ed42bf957', NULL, 'Creio! Ajuda minha incredulidade!', 'Marcos 9:24', 'Duvidar não é perder a fé — é ser honesto com Deus. Ele acolhe nossa honestidade e fortalece nossa fé.', 'Senhor, creio! Ajuda minha incredulidade! Amém.', 'Se tem dúvidas, converse com Deus sobre elas hoje.', '{"Duvidar é pecado?","O que fazer quando a dúvida aparece?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 7, 'Quando a dúvida bate', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('790849ac-cf16-4f06-93d1-5bcedb792abd', NULL, 'Pelos seus frutos os conhecereis.', 'Mateus 7:16-17', 'Boas obras não são a raiz da salvação, mas o fruto dela. Se há fruto, a raiz é saudável.', 'Senhor, que minha vida produza frutos que confirmem Tua graça. Amém.', 'Observe os frutos espirituais na sua vida como evidência da obra de Deus.', '{"Qual a diferença entre fruto e raiz da salvação?","Que frutos você percebe na sua vida?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 8, 'Frutos, não raízes', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('aacece25-e3a2-4e4a-922e-490e18123026', NULL, 'Ele nos salvou pela lavagem da regeneração e renovação do Espírito Santo.', 'Tito 3:5', 'O Batismo é selo visível da graça invisível. Deus já agiu por você — o Batismo confirma isso.', 'Pai, obrigado pelo Batismo que sela Tua promessa em minha vida. Amém.', 'Relembre seu batismo (ou seu significado) e agradeça.', '{"Como o Batismo se relaciona com a certeza da salvação?","O que o Batismo sela?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 9, 'Batismo como selo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('32aeb09e-5d10-4a74-9042-c1acf1f95bf7', NULL, 'Sereis minhas testemunhas.', 'Atos 1:8', 'Testemunha é quem conta o que viu e viveu. Não precisa ser teólogo — basta contar sua história com Jesus.', 'Espírito, faz de mim Tua testemunha. Amém.', 'Escreva em 3 frases o que Jesus fez por você.', '{"O que é ser testemunha?","Qual é a sua história com Jesus?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 2, 'Testemunhas de Cristo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('befcad5c-83a3-4f6e-a21d-f416dcafcb1c', NULL, 'Resta um repouso para o povo de Deus.', 'Hebreus 4:9-10', 'A certeza da salvação nos permite descansar — não na preguiça, mas na confiança. A obra é de Deus. Descanse nEle.', 'Senhor, descanso em Tua graça. Minha salvação está segura. Amém.', 'Prepare-se para o encontro escrevendo 3 razões pelas quais tem certeza da salvação.', '{"O que significa descansar na graça?","Você consegue descansar ou vive tentando \"merecer\"?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '503f7331-95b3-42e3-a66b-10830d50aa8e', 10, 'Descansando na graça', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('40f39a0c-eb00-4646-8f8f-e79d0f2e782e', NULL, 'Deus, sendo rico em misericórdia, nos deu vida com Cristo.', 'Efésios 2:4-5', 'A graça de Deus é surpreendente — Ele nos deu vida quando estávamos mortos em pecados. Não merecemos, mas recebemos.', 'Deus de misericórdia, Tua graça me surpreende todos os dias. Amém.', 'Liste 3 formas como a graça de Deus te surpreendeu.', '{"A graça de Deus já te surpreendeu? Como?","O que torna a graça tão especial?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 1, 'Graça que surpreende', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('943d23da-0098-4055-ab69-014161625c65', NULL, 'Fé é a certeza de coisas que se esperam, a convicção de fatos que se não veem.', 'Hebreus 11:1', 'A fé não é ilusão — é convicção fundamentada nas promessas de Deus. E até ela é um presente dEle para nós.', 'Senhor, aumenta minha fé. Ela é Teu presente para mim. Amém.', 'Exercite a fé: confie em Deus para algo que não pode controlar hoje.', '{"Fé é crer no impossível ou confiar no invisível?","Como a fé se manifesta na prática?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 2, 'Fé: presente de Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('f87d420e-f8aa-4665-837a-39a31a9c7ec7', NULL, 'Se alguém está em Cristo, é nova criatura; as coisas antigas já passaram.', '2 Coríntios 5:17', 'Em Cristo, você não é uma versão melhorada do que era — você é NOVO. As coisas velhas ficaram para trás.', 'Deus, obrigado por me fazer novo. As coisas velhas passaram! Amém.', 'Identifique algo "velho" que ainda carrega e entregue a Deus.', '{"O que mudou ou está mudando desde que você está em Cristo?","Há algo \"velho\" que precisa ser deixado para trás?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 3, 'Nova criatura', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('c7374bb4-0943-41a6-8f8c-1ccc4a8364d6', NULL, 'Fostes chamados à liberdade; porém não useis da liberdade para dar ocasião à carne.', 'Gálatas 5:13', 'A graça nos liberta, mas não para viver como quisermos — para viver como devemos: em amor e serviço.', 'Senhor, usa minha liberdade para Te servir e amar o próximo. Amém.', 'Reflita: há alguma liberdade que você usa como desculpa para pecar?', '{"Qual a diferença entre liberdade e licença?","Como usar a liberdade com responsabilidade?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 4, 'Liberdade, não licença', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('9bbdbde3-6e68-4147-9731-738b3c553c48', NULL, 'Transformai-vos pela renovação da vossa mente.', 'Romanos 12:2', 'A nova vida não é instantânea em tudo — é um processo diário de renovação. Cada dia Deus nos transforma mais.', 'Renova minha mente, Senhor, dia após dia. Amém.', 'Identifique um pensamento que precisa ser renovado à luz da Palavra.', '{"A transformação cristã é instantânea ou processual?","Que pensamentos precisam ser renovados em você?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 5, 'Transformação contínua', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('663eb047-ecdf-46a7-a9a7-56bde90286b5', NULL, 'Andai pelo Espírito e não havereis de cumprir os desejos da carne.', 'Gálatas 5:16', 'A nova vida é vivida pelo Espírito — não por esforço próprio. É dependência diária da graça.', 'Espírito Santo, guia meus passos hoje. Não quero viver por esforço, mas por Ti. Amém.', 'Antes de cada decisão hoje, pause e peça direção ao Espírito.', '{"O que significa andar pelo Espírito?","Como diferenciar carne e Espírito no dia a dia?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 6, 'Viver pelo Espírito', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b4d6c36b-f4ec-496e-9899-c5b55d031f91', NULL, 'O fruto do Espírito é: amor, alegria, paz, paciência, amabilidade, bondade, fidelidade, mansidão, domínio próprio.', 'Gálatas 5:22-23', 'O fruto do Espírito não é produzido por esforço — cresce quando permanecemos em Cristo. É natural, não forçado.', 'Espírito, produz Teu fruto em mim naturalmente. Amém.', 'Identifique qual fruto do Espírito mais precisa crescer em você.', '{"Qual fruto do Espírito é mais difícil para você?","Como cultivar esses frutos?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 7, 'Fruto do Espírito', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('91324cc4-7a53-4a9d-8332-c8d0f51fc1f5', NULL, 'Se confessarmos os nossos pecados, Ele é fiel e justo para nos perdoar.', '1 João 1:9', 'A nova vida não é perfeição — é recomeço. Quando caímos, a graça nos levanta. Confissão é o caminho.', 'Pai, confesso meus pecados. Obrigado pela graça que me permite recomeçar. Amém.', 'Se há algo para confessar, faça hoje e receba o perdão.', '{"A vida cristã é perfeição ou recomeço?","Por que a confissão é tão importante?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 8, 'Graça para recomeçar', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('652c6aaa-e27e-4285-b429-62612f9bb96c', NULL, 'Somos feitura dEle, criados em Cristo Jesus para boas obras.', 'Efésios 2:10', 'A nova vida tem propósito: fomos criados para boas obras. Não PARA ser salvos, mas PORQUE fomos salvos.', 'Senhor, mostra-me as boas obras que preparaste para mim. Amém.', 'Faça uma boa obra intencional hoje.', '{"Qual o propósito das boas obras na vida cristã?","Que boas obras Deus preparou para você?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 9, 'Vivendo com propósito', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('a513036a-cde9-4b22-9190-8e5b0cb13f62', NULL, 'Se fostes ressuscitados com Cristo, buscai as coisas lá do alto.', 'Colossenses 3:1-3', 'A nova vida não é só futura — é agora. Fomos ressuscitados com Cristo e podemos viver diferente hoje mesmo.', 'Senhor, ajuda-me a viver a nova vida HOJE, buscando as coisas do alto. Amém.', 'Prepare-se para o encontro listando mudanças que a graça trouxe à sua vida.', '{"Como a nova vida se manifesta no seu cotidiano?","O que mudou em você nessas duas semanas?"}', '2026-02-24 21:50:50.356805+00', '2026-05-13 12:53:51.627337+00', '67a5341d-a934-4387-a16c-1802e3e7b092', 10, 'A nova vida é agora', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('fcd18bbc-7f72-46bd-811b-e37503998dad', NULL, 'Toda Escritura é inspirada por Deus e útil para o ensino.', '2 Timóteo 3:16', 'A Bíblia não é apenas um livro humano — é a Palavra de Deus, inspirada pelo Espírito Santo.', 'Senhor, obrigado pela Tua Palavra inspirada. Abre meu coração para ouvir. Amém.', 'Comece a leitura bíblica com uma oração pedindo entendimento.', '{"O que significa a Bíblia ser inspirada?","Isso muda como você a lê?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 1, 'Inspirada por Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b0602306-f11f-434d-8511-76600f641815', NULL, 'A palavra de Deus é viva, eficaz e mais cortante que espada de dois gumes.', 'Hebreus 4:12', 'A Bíblia não é letra morta — é viva e age em nós. Ela discerne pensamentos e intenções do coração.', 'Senhor, que Tua Palavra viva penetre meu coração. Amém.', 'Ao ler a Bíblia hoje, pergunte: "O que isso diz sobre mim?"', '{"Você já sentiu a Bíblia falando diretamente com você?","O que significa a Palavra ser \"viva\"?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 2, 'Viva e eficaz', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('0f38b074-d494-4ce6-8989-da019daf6503', NULL, 'Lâmpada para os meus pés é a tua palavra e luz para o meu caminho.', 'Salmo 119:105', 'Num mundo confuso, a Bíblia ilumina o caminho. Ela nos dá direção clara quando tudo parece escuro.', 'Senhor, ilumina meu caminho com Tua Palavra. Amém.', 'Em uma decisão que precisa tomar, busque orientação na Bíblia.', '{"Como a Bíblia ilumina suas decisões?","Você a consulta regularmente?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 3, 'Lâmpada e luz', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('bfabf6d9-265b-4a3a-8356-0c0346d5f7a2', NULL, 'Começando por Moisés e todos os profetas, explicou-lhes o que constava a Seu respeito em todas as Escrituras.', 'Lucas 24:27', 'Do Gênesis ao Apocalipse, a Bíblia conta a história de Deus resgatando Seu povo. Jesus é o centro de tudo.', 'Senhor, ajuda-me a ver Jesus em toda a Escritura. Amém.', 'Leia um capítulo do Antigo Testamento e identifique como aponta para Jesus.', '{"Qual a história central da Bíblia?","Como o AT e o NT se conectam?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 4, 'A Bíblia toda conta uma história', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('da79b497-ec25-4430-b045-4a91a8775f4a', NULL, 'Medita nele dia e noite para que tenhas cuidado de fazer segundo tudo quanto nele está escrito.', 'Josué 1:8', 'Existem formas práticas de ler a Bíblia: devocional, estudo, meditação. Cada uma tem seu valor.', 'Senhor, ensina-me a meditar na Tua Palavra dia e noite. Amém.', 'Experimente o método SOAP: Scripture, Observation, Application, Prayer.', '{"Qual método de leitura bíblica funciona melhor para você?","Você tem uma rotina de leitura?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 5, 'Métodos de leitura', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('a511690e-8053-4dcf-af4f-62d93a4e43af', NULL, 'Nem só de pão viverá o homem, mas de toda palavra que procede da boca de Deus.', 'Mateus 4:4', 'Assim como o corpo precisa de comida, o espírito precisa da Palavra. Ler a Bíblia é alimentar a alma.', 'Senhor, alimenta-me com Tua Palavra. Sem ela, minha alma padece. Amém.', 'Substitua 15 minutos de redes sociais por leitura bíblica.', '{"Você tem \"fome\" da Palavra de Deus?","O que acontece quando não se alimenta espiritualmente?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 6, 'Palavra que alimenta', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('7c81f049-be57-4dd3-8f99-3779fe5a95d3', NULL, 'Quando vier o Espírito da verdade, Ele vos guiará a toda a verdade.', 'João 16:13', 'Não lemos a Bíblia sozinhos — o Espírito Santo é nosso intérprete. Ele abre nosso entendimento.', 'Espírito Santo, guia-me na leitura da Palavra. Amém.', 'Antes de ler a Bíblia, peça ao Espírito Santo para iluminar o texto.', '{"Qual o papel do Espírito Santo na leitura bíblica?","Você ora antes de ler?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 7, 'A Bíblia e o Espírito', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('931daeee-c2de-42f8-b077-64c1f56c8203', NULL, 'Sede praticantes da palavra e não somente ouvintes.', 'Tiago 1:22', 'Ler não basta — precisamos praticar. A Bíblia foi escrita para transformar vidas, não apenas informar mentes.', 'Senhor, não me deixes ser apenas ouvinte. Ajuda-me a praticar. Amém.', 'Escolha um versículo e aplique-o concretamente hoje.', '{"Qual a diferença entre ouvir e praticar?","Qual versículo você precisa colocar em prática?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 8, 'Aplicando a Palavra', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('22535538-cd54-4028-9d6b-a77a510e8312', NULL, 'Escondi a tua palavra no meu coração para não pecar contra ti.', 'Salmo 119:11', 'Memorizar a Bíblia não é exercício acadêmico — é proteção espiritual. A Palavra guardada no coração nos protege.', 'Senhor, grava Tua Palavra em meu coração. Amém.', 'Memorize o versículo de hoje: Salmo 119:11.', '{"Você já memorizou versículos? Quais?","Como a memorização pode te ajudar no dia a dia?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 9, 'Memorizar a Palavra', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('370a41f3-aa6d-4771-b4d2-659872040e32', NULL, 'Bem-aventurado o homem que medita na lei do Senhor de dia e de noite.', 'Salmo 1:1-3', 'A promessa é clara: quem medita na Palavra é como árvore plantada junto a águas — firme, frutífera, próspera.', 'Senhor, quero ser como árvore junto às águas, enraizado em Tua Palavra. Amém.', 'Prepare-se para o encontro resumindo o que aprendeu sobre a Bíblia.', '{"Você é mais parecido com uma árvore firme ou com palha ao vento?","O que te ajudaria a meditar mais?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b91ed895-87ca-4876-a954-947f301d2bbb', 10, 'A Bíblia e minha vida', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('8997b0b4-1cda-46ea-bb79-29b5ee9f7303', NULL, 'Perto está o Senhor de todos os que O invocam.', 'Salmo 145:18', 'Deus não é distante — Ele está perto de quem O busca. Ele quer ouvir sua voz, seus medos, suas alegrias.', 'Pai, obrigado por estar perto quando eu Te invoco. Amém.', 'Fale com Deus de forma simples e honesta hoje.', '{"Você acredita que Deus quer ouvir você?","O que te impede de orar mais?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 1, 'Deus quer ouvir você', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('9be071da-afeb-483b-8236-34f7ffb49052', NULL, 'Pai nosso que estás nos céus, santificado seja o teu nome.', 'Mateus 6:9', 'Jesus nos ensinou a chamar Deus de Pai. A oração começa com relacionamento, não com formalidade.', 'Pai nosso, santificado seja o Teu nome. Amém.', 'Ore o Pai Nosso lentamente, parando em cada frase.', '{"O que significa chamar Deus de Pai?","Como isso muda sua oração?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 2, 'Pai Nosso: modelo de oração', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('3658f8d7-d3c5-4329-8214-3d91906e7622', NULL, 'Venha o teu Reino, faça-se a tua vontade.', 'Mateus 6:10', 'Orar pelo Reino é pedir que a vontade de Deus prevaleça — em nós, em nosso redor, no mundo.', 'Senhor, venha o Teu Reino. Que Tua vontade prevaleça sobre a minha. Amém.', 'Ore por uma situação ao seu redor onde o Reino de Deus precisa agir.', '{"O que é o Reino de Deus?","Como ele se manifesta na sua vida?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 3, 'Venha o Teu Reino', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('9f847d8e-2423-4584-9cae-b4aa97904e4c', NULL, 'O pão nosso de cada dia nos dá hoje.', 'Mateus 6:11', 'Pedir o pão diário é reconhecer dependência. Não pedimos para um ano — pedimos para hoje. É confiança diária.', 'Pai, confio em Ti para suprir o que preciso hoje. Amém.', 'Agradeça por cada refeição hoje, reconhecendo que vem de Deus.', '{"Você reconhece sua dependência diária de Deus?","O que significa o \"pão de cada dia\" na sua vida?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 4, 'O pão de cada dia', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('688705af-166d-495d-b60d-c7f725365465', NULL, 'Perdoa-nos as nossas dívidas, assim como nós perdoamos.', 'Mateus 6:12', 'Perdão recebido e perdão concedido caminham juntos. Quem foi perdoado é chamado a perdoar.', 'Pai, perdoa-me e ajuda-me a perdoar os outros. Amém.', 'Há alguém que você precisa perdoar? Ore por essa pessoa.', '{"Por que o perdão é tão difícil?","Há alguém que precisa do seu perdão?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 5, 'Perdoa como perdoamos', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('7f3d9c65-928a-4256-b695-13fe9b22c6b7', NULL, 'Não nos deixes cair em tentação, mas livra-nos do mal.', 'Mateus 6:13', 'Reconhecemos nossa fraqueza e pedimos proteção. Deus é nosso refúgio contra o mal.', 'Pai, protege-me do mal. Sou fraco, mas Tu és forte. Amém.', 'Ore pela proteção espiritual da sua família e amigos.', '{"Contra que tipo de mal você precisa de proteção?","Deus realmente nos protege?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 6, 'Livra-nos do mal', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('118e38e2-8ad2-4834-ac6b-63e995fdb2f4', NULL, 'Orai sem cessar.', '1 Tessalonicenses 5:17', 'Orar sem cessar não é ficar de joelhos 24h — é manter uma consciência constante da presença de Deus.', 'Senhor, quero viver consciente da Tua presença o tempo todo. Amém.', 'Ao longo do dia, faça "micro-orações" de 10 segundos.', '{"É possível orar sem cessar? Como?","O que significa viver em oração?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 7, 'Orar sem cessar', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('5a37d96a-2637-452d-a6cf-b292c616348f', NULL, 'Até quando, Senhor? Esquecer-te-ás de mim para sempre?', 'Salmo 13:1-2', 'Mesmo quando Deus parece silencioso, Ele está presente. Os salmos nos ensinam a ser honestos com Deus.', 'Senhor, mesmo no silêncio, eu confio em Ti. Amém.', 'Se está vivendo um silêncio de Deus, escreva seus sentimentos como o salmista.', '{"Você já sentiu Deus em silêncio?","O que fazer quando isso acontece?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 8, 'Quando Deus parece silencioso', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('ee25da13-1a0b-4e98-8726-65f0befacc96', NULL, 'Onde dois ou três estiverem reunidos em meu nome, ali estou no meio deles.', 'Mateus 18:20', 'Orar juntos multiplica a força e a presença de Deus. A oração comunitária é poderosa.', 'Jesus, obrigado por estar no meio de nós quando oramos juntos. Amém.', 'Convide alguém para orar com você hoje.', '{"Qual a diferença entre orar sozinho e em grupo?","Você ora com outros regularmente?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 9, 'Oração em comunidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('7efea053-e97a-4a2d-8cfe-732e0adccc32', NULL, 'Não andeis ansiosos, mas em tudo fazei conhecidos os vossos pedidos diante de Deus.', 'Filipenses 4:6-7', 'A oração é o antídoto para a ansiedade. Quando levamos tudo a Deus, a paz que excede o entendimento vem.', 'Pai, deposito toda minha ansiedade em Ti. Tua paz me guarda. Amém.', 'Prepare-se para o encontro: escreva como sua vida de oração evoluiu nestas duas semanas.', '{"A oração tem diminuído sua ansiedade?","O que você aprendeu sobre oração?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', '599ee650-8e31-4f6b-96e5-e03e2575c5bb', 10, 'Minha vida de oração', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('5c234ac7-1d7a-49df-8ab3-16433f210a24', NULL, 'Jesus foi tentado em todas as coisas, à nossa semelhança, mas sem pecado.', 'Hebreus 4:15', 'Ser tentado não é pecado — até Jesus foi tentado. O pecado está em ceder, não em sentir a tentação.', 'Jesus, obrigado por entender minhas tentações. Ajuda-me a resistir. Amém.', 'Quando a tentação vier hoje, lembre-se: sentir não é ceder.', '{"Qual a diferença entre tentação e pecado?","Saber que Jesus foi tentado te ajuda?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 1, 'Tentação não é pecado', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('664fac0d-b8ef-4945-8afc-2544523e780f', NULL, 'Deus é fiel e não permitirá que sejais tentados além das vossas forças, mas dará o livramento.', '1 Coríntios 10:13', 'Deus promete: sempre há saída. Nenhuma tentação é irresistível quando confiamos nEle.', 'Pai fiel, mostra-me a saída em cada tentação. Amém.', 'Na próxima tentação, procure a "porta de saída" que Deus oferece.', '{"Você acredita que sempre há saída?","Qual tentação parece mais difícil de resistir?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 2, 'A saída que Deus dá', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('7606f7d9-2048-46e3-ae1b-fe1afeead918', NULL, 'Cada um é tentado pela sua própria cobiça, quando esta o atrai e seduz.', 'Tiago 1:14-15', 'A tentação nasce dentro de nós — dos nossos desejos desordenados. Conhecer isso é o primeiro passo para vencer.', 'Senhor, transforma meus desejos. Purifica meu coração. Amém.', 'Identifique um desejo que frequentemente te leva à tentação.', '{"De onde vem a tentação?","Conhecer a origem ajuda a resistir?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 3, 'A origem da tentação', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('bffb0b9f-9b5b-4b52-9601-497232f38867', NULL, 'Revesti-vos de toda a armadura de Deus.', 'Efésios 6:11', 'Deus nos deu armadura: verdade, justiça, Evangelho, fé, salvação, Palavra e oração. Não lutamos desarmados.', 'Senhor, reveste-me com Tua armadura hoje. Amém.', 'Visualize cada peça da armadura e "vista-a" em oração.', '{"Quais peças da armadura são mais difíceis de usar?","Como você se prepara para a luta espiritual?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 4, 'Armadura espiritual', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b98dd779-7d0e-420b-81c2-a9405fc937a2', NULL, 'Foge das paixões da mocidade.', '2 Timóteo 2:22', 'Às vezes, vencer é fugir. Nem toda batalha se vence lutando — algumas se vencem evitando.', 'Senhor, dá-me coragem para fugir quando necessário. Amém.', 'Identifique situações que você deveria evitar em vez de enfrentar.', '{"Fugir é fraqueza ou sabedoria?","Do que você precisa fugir?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 5, 'Fugir é coragem', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b52c34a3-660a-418f-8be2-51e965a71f30', NULL, 'Confessai os vossos pecados uns aos outros e orai uns pelos outros para serdes curados.', 'Tiago 5:16', 'Pecado escondido tem poder. Confessado, perde a força. Confessar não é fraqueza — é caminho de cura.', 'Senhor, dá-me coragem para confessar e buscar cura. Amém.', 'Confesse a Deus (e se possível a um irmão de confiança) algo que carrega.', '{"Por que a confissão é tão difícil?","Há algo que precisa ser confessado?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 6, 'O poder da confissão', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('a0017fb5-ef7b-438c-95d7-fc5bb9aab59b', NULL, 'Miserável homem que eu sou! Graças a Deus por Jesus Cristo!', 'Romanos 7:24-25', 'Paulo foi honesto: sozinhos não vencemos. Mas em Cristo há libertação. A graça é mais forte que o pecado.', 'Jesus, sem Ti não consigo. Com Ti, sou mais que vencedor. Amém.', 'Repita ao longo do dia: "A graça é mais forte que meu pecado."', '{"Você se identifica com Paulo em Romanos 7?","Como a graça supera o pecado?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 7, 'Dependência da graça', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('df1b6c84-6e51-40d1-b690-7a848caad8a3', NULL, 'Melhor é serem dois do que um, porque se um cair, o outro o levanta.', 'Eclesiastes 4:9-10', 'Não fomos feitos para lutar sozinhos. A comunidade é proteção contra a tentação.', 'Senhor, obrigado pelos irmãos que caminham comigo. Amém.', 'Peça a alguém de confiança para ser seu parceiro de accountability.', '{"Você tem alguém com quem pode ser transparente?","Como a comunidade protege contra tentação?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 8, 'Comunidade como proteção', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('69df03fa-d27b-47f5-80c3-aec1883df805', NULL, 'Não que eu o tenha já alcançado; mas uma coisa faço: prossigo para o alvo.', 'Filipenses 3:12', 'A vitória sobre o pecado é gradual, não instantânea. O importante é não desistir de prosseguir.', 'Senhor, mesmo nas quedas, ajuda-me a levantar e prosseguir. Amém.', 'Se caiu recentemente, levante-se. Confesse e continue.', '{"Você costuma desistir após uma queda?","O que significa prosseguir para o alvo?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 9, 'Vitória gradual', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('e2d44feb-1da2-4c06-82f8-d728b40ce766', NULL, 'Em todas estas coisas somos mais que vencedores por Aquele que nos amou.', 'Romanos 8:37', 'A promessa final: em Cristo somos MAIS que vencedores. Não pela nossa força, mas pelo Seu amor.', 'Jesus, em Ti sou mais que vencedor. Obrigado! Amém.', 'Prepare-se para o encontro: como você pretende lutar contra a tentação a partir de agora?', '{"O que significa ser \"mais que vencedor\"?","Qual foi sua maior lição sobre tentação nestas semanas?"}', '2026-02-24 21:52:36.029677+00', '2026-05-13 12:53:51.627337+00', 'b17a5890-6d54-4c6d-a4ca-4b5f023670b9', 10, 'Mais que vencedor', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('25f0fc5e-1de8-47c1-b59d-c2eef55e54cc', NULL, 'Vós sois corpo de Cristo e, individualmente, membros desse corpo.', '1 Coríntios 12:27', 'A Igreja não é um prédio — somos nós. Cada membro importa, cada um tem sua função no corpo.', 'Senhor, obrigado por me fazer parte do Teu corpo. Amém.', 'Pense em qual parte do corpo você é e como pode servir.', '{"O que significa ser membro do corpo de Cristo?","Qual sua função?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 1, 'Corpo de Cristo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('ecfcada4-14dd-41f3-9fb1-54698ddd49ed', NULL, 'Perseveravam na doutrina, comunhão, partir do pão e orações.', 'Atos 2:42', 'A primeira igreja era simples mas profunda: doutrina, comunhão, Ceia e oração. Esse é o DNA da Igreja.', 'Senhor, restaura em nós o DNA da Igreja primitiva. Amém.', 'Compare sua vida na igreja com Atos 2:42.', '{"O que a Igreja primitiva tinha que às vezes nos falta?","Qual dessas 4 práticas é mais fraca na sua vida?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 2, 'A Igreja primitiva', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('aa85be2c-311f-4d84-8e02-b3b298f7fcd1', NULL, 'Vós mesmos, como pedras que vivem, sois edificados casa espiritual.', '1 Pedro 2:5', 'Somos pedras vivas na construção de Deus. Cada um tem seu lugar e importância na edificação.', 'Pai, usa-me como pedra viva na Tua construção. Amém.', 'Encoraje alguém da comunidade — eles também são pedra viva!', '{"O que significa ser pedra viva?","Você se sente parte da construção?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 3, 'Pedras vivas', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('05e9528f-f17c-43c3-9fda-fd2b5e660095', NULL, 'Já não sois estrangeiros, mas concidadãos dos santos e membros da família de Deus.', 'Efésios 2:19', 'Na Igreja, não somos estrangeiros — somos família. Pertencemos uns aos outros.', 'Pai, obrigado pela família espiritual que me deste. Amém.', 'Trate alguém da comunidade como família hoje.', '{"Você se sente parte da família de Deus?","O que falta para sentir mais pertencimento?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 4, 'Família de Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('59496570-6cc3-4094-b87e-ba81cf6a87f6', NULL, 'Ide, fazei discípulos de todas as nações.', 'Mateus 28:19-20', 'A Igreja existe para fazer discípulos. Não para ficar confortável dentro de quatro paredes, mas para ir ao mundo.', 'Senhor, faça de mim um discípulo que faz discípulos. Amém.', 'Ore pela missão da Igreja no mundo.', '{"Qual a missão principal da Igreja?","Como você participa dessa missão?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 5, 'A missão da Igreja', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('3931efd5-f4f9-4445-8e7d-43724e7fbfea', NULL, 'Nada façais por rivalidade, mas por humildade.', 'Filipenses 2:2-3', 'A Igreja é feita de pessoas imperfeitas. Haverá conflitos. Mas a humildade e o amor superam.', 'Senhor, dá-me graça para amar a Igreja imperfeita. Amém.', 'Perdoe algo que te incomodou na comunidade.', '{"Como lidar com decepções na igreja?","A perfeição é possível na Igreja?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 6, 'Igreja imperfeita', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('43dbc50b-4d07-4ae4-afc5-a42ea7694ba0', NULL, 'Há diversidade de dons, mas o Espírito é o mesmo.', '1 Coríntios 12:4-7', 'Cada membro tem dons diferentes — e todos são necessários. A diversidade é o plano de Deus.', 'Espírito, mostra-me meus dons para servir o corpo. Amém.', 'Identifique um dom que pode usar para servir.', '{"Quais dons você percebe em si?","Como eles servem ao corpo?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 7, 'Dons e serviço', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('55c545ea-a647-4cae-9c4c-e2301886b245', NULL, 'Não deixemos de congregar-nos.', 'Hebreus 10:25', 'A fé cristã não é individual — precisa da comunidade local. Congregar é obediência e necessidade.', 'Senhor, obrigado pela minha comunidade local. Amém.', 'Comprometa-se a estar presente no próximo encontro.', '{"Por que é importante ter uma comunidade local?","O que te mantém na igreja?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 8, 'Igreja local', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('f29a34b2-56ac-4b54-84b2-a1a2408f8915', NULL, 'Não peço que os tires do mundo, mas que os guardes do mal.', 'João 17:15-18', 'A Igreja está NO mundo mas não É do mundo. Somos enviados, não isolados.', 'Jesus, guarda-me do mal enquanto estou no mundo. Amém.', 'Pense em como ser presença de Cristo no ambiente onde vive.', '{"Como ser da igreja sem se isolar do mundo?","Qual seu papel como cristão na sociedade?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 9, 'Igreja e mundo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('10332280-342f-40de-b0fc-4afbc46e33d7', NULL, 'Assim como num só corpo temos muitos membros, assim também nós somos um só corpo em Cristo.', 'Romanos 12:4-5', 'Cada um tem um lugar. Encontrar o seu é parte do discipulado. Você importa para o corpo!', 'Senhor, mostra-me meu lugar no Teu corpo. Quero servir. Amém.', 'Prepare-se para o encontro: onde você se encaixa na igreja?', '{"Onde você se sente mais útil na igreja?","O que te impede de se envolver mais?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', '468c87a8-5373-4b1c-9e43-9816481f4e26', 10, 'Meu lugar na Igreja', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('61c33d31-b19a-4bdd-a9dd-c6851671aec3', NULL, 'Batizando-os em nome do Pai, do Filho e do Espírito Santo.', 'Mateus 28:19', 'O Batismo foi ordenado por Jesus. Não é opcional nem mero ritual — é mandamento do Senhor.', 'Jesus, obrigado pelo dom do Batismo. Amém.', 'Pesquise na Bíblia passagens sobre o Batismo.', '{"Por que Jesus ordenou o Batismo?","Batismo é opcional?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 1, 'O Batismo na Bíblia', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('a13c1d6f-3b17-4491-b543-1fb7e0b7d730', NULL, 'Fomos sepultados com Ele pelo batismo na morte, para que andemos em novidade de vida.', 'Romanos 6:3-4', 'O Batismo é morte e ressurreição: morremos para o pecado e vivemos para Deus. Nova vida começa aqui.', 'Senhor, vivo a novidade de vida do meu Batismo. Amém.', 'Reflita: o que "morreu" em você pelo Batismo?', '{"O que significa morrer e ressuscitar com Cristo?","Isso é real ou simbólico?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 2, 'Morrer e ressuscitar', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b96d43c2-f081-4522-a381-5aeeddbb84f9', NULL, 'Todos vós que fostes batizados em Cristo de Cristo vos revestistes.', 'Gálatas 3:27', 'No Batismo, vestimos Cristo. Ele é nossa identidade, nossa roupa espiritual.', 'Cristo, me reveste. Que eu reflita Tua imagem. Amém.', 'Declare: "Estou revestido de Cristo" e viva isso hoje.', '{"O que significa se revestir de Cristo?","Como isso se manifesta no dia a dia?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 3, 'Revestidos de Cristo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('3f1c3a5e-7d58-4435-9b80-f2075b1d176a', NULL, 'Estabelecerei minha aliança entre mim e ti e a tua descendência.', 'Gênesis 17:7', 'O Batismo é sinal de aliança — Deus se compromete conosco. Não somos nós que nos seguramos em Deus; Ele nos segura.', 'Pai, obrigado pela aliança que firmaste comigo. Amém.', 'Medite na fidelidade de Deus à Sua aliança.', '{"O que é aliança?","Como o Batismo é sinal de aliança?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 4, 'Aliança de Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('30d4e711-9ca0-4b7f-ba9f-a7e6b5661604', NULL, 'Foi batizado, ele e todos os seus.', 'Atos 16:33', 'Na tradição luterana, batizamos crianças porque a graça precede a fé. Deus age primeiro — sempre.', 'Senhor, obrigado por agir antes mesmo de eu poder responder. Amém.', 'Se foi batizado como criança, agradeça pela graça que te alcançou antes da sua consciência.', '{"Por que batizar crianças?","A graça depende da nossa resposta?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 5, 'Batismo de crianças', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('8a602431-e2b4-414b-a48a-83fc85f4c892', NULL, 'Quando o diabo te acusar, dize: "Sou batizado!"', 'Martinho Lutero', 'Lutero nos ensinou: o Batismo é arma contra acusação. Quando o medo bater, lembre: eu sou batizado!', 'Sou batizado! Pertenço a Deus! Nada me separa dEle. Amém.', 'Na próxima crise, declare: "Eu sou batizado!"', '{"Você lembra do seu Batismo em momentos difíceis?","Como o Batismo é conforto?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 6, 'Lembrar do Batismo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('36b643a6-ab72-42a7-b920-6899db9f98ce', NULL, 'Um só Senhor, uma só fé, um só batismo.', 'Efésios 4:5', 'O Batismo nos une a Cristo e uns aos outros. É marca de identidade compartilhada.', 'Senhor, somos um pelo Batismo. Unidos em Ti. Amém.', 'Ore por outros batizados da sua comunidade.', '{"O Batismo une os cristãos? Como?","Você se sente unido a outros pelo Batismo?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 7, 'Identidade batismal', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('cbda10f1-aa90-4702-b7b0-c5269f16361f', NULL, 'O velho Adão em nós deve afogar-se pelo arrependimento diário.', 'Lutero, Catecismo Menor', 'Lutero ensinou que o Batismo é diário: cada dia morremos para o pecado e ressuscitamos para a nova vida.', 'Senhor, afoga o velho em mim hoje. Ressuscita o novo. Amém.', 'Comece o dia "lembrando" seu Batismo.', '{"Como viver o Batismo diariamente?","O que precisa morrer hoje em você?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 8, 'Viver o Batismo diariamente', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('f6ebdf2f-a476-4610-be2b-516c73738c13', NULL, 'Não temas, porque eu te remi; chamei-te pelo teu nome, tu és meu.', 'Isaías 43:1', 'A promessa do Batismo não expira. Deus te chamou pelo nome — você pertence a Ele para sempre.', 'Pai, sou Teu. Tu me chamaste pelo nome. Amém.', 'Repita durante o dia: "Eu sou de Deus. Ele me chamou pelo nome."', '{"A promessa do Batismo pode falhar?","Como isso traz segurança?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 9, 'A promessa permanece', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('ff00d216-e5fc-45d0-9052-b784829f27f6', NULL, 'Se confessares com tua boca que Jesus é Senhor e creres, serás salvo.', 'Romanos 10:9', 'A Confirmação é sua resposta pessoal ao que Deus fez no Batismo. É dizer "sim" ao que Ele já disse "sim".', 'Senhor, digo SIM ao que fizeste em meu Batismo. Amém.', 'Prepare-se para o encontro: escreva por que você quer confirmar sua fé.', '{"Qual a relação entre Batismo e Confirmação?","O que significa dizer \"sim\" a Deus?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'c3eda274-c1f2-4adf-8b4f-b93d9033ebd3', 10, 'Confirmação e Batismo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('a0fab375-225f-4731-b751-9f149e08d65c', NULL, 'Isto é o meu corpo dado por vós; fazei isto em memória de mim.', 'Lucas 22:19-20', 'Na última noite, Jesus instituiu a Ceia. Pão e vinho — Seu corpo e sangue entregues por amor.', 'Jesus, obrigado por entregar Teu corpo e sangue por mim. Amém.', 'Leia o relato da última ceia em Lucas 22.', '{"O que aconteceu na última ceia?","Por que Jesus disse \"fazei isto em memória de mim\"?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 1, 'A última ceia', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('8aeb5074-7093-4987-ae78-1d3a7f8a7060', NULL, 'Isto É o meu corpo.', 'Mateus 26:26', 'Luteranos creem que Cristo está REALMENTE presente no pão e no vinho — não é só símbolo.', 'Jesus, Tu estás realmente presente na Ceia. Que mistério maravilhoso! Amém.', 'Medite no mistério da presença real de Cristo.', '{"O que significa \"presença real\"?","Isso muda como você participa da Ceia?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 2, 'Presença real', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('51f91c80-c3a9-4e82-86b3-8229aa9dff85', NULL, 'Isto é o meu sangue da nova aliança, derramado para remissão de pecados.', 'Mateus 26:28', 'Na Ceia, recebemos perdão real. O sangue de Cristo nos purifica — toda vez que participamos.', 'Jesus, recebo o perdão do Teu sangue. Purifica-me. Amém.', 'Confesse seus pecados antes de participar da próxima Ceia.', '{"O que o sangue de Cristo faz por nós?","Como nos preparamos para a Ceia?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 3, 'Perdão na Ceia', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('477fe575-2fe6-4b4b-8a1b-0e9ffe715f64', NULL, 'Todas as vezes que comerdes e beberdes, anunciais a morte do Senhor até que Ele venha.', '1 Coríntios 11:26', 'A Ceia fortalece a fé porque nos conecta diretamente à morte e ressurreição de Cristo.', 'Senhor, fortalece minha fé a cada Ceia. Amém.', 'Na próxima Ceia, participe com coração aberto e expectante.', '{"Como a Ceia fortalece sua fé?","Você espera algo ao participar?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 4, 'Fortalecimento da fé', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('bcb1d59a-2fc8-4a90-8e43-52acc7cf84d7', NULL, 'Nós, embora muitos, somos um só corpo, porque todos participamos do mesmo pão.', '1 Coríntios 10:17', 'A Ceia nos une — não somos indivíduos isolados, mas um corpo partilhando a mesma mesa.', 'Senhor, que a Tua mesa nos una como família. Amém.', 'Na próxima Ceia, olhe para os irmãos ao seu lado e agradeça.', '{"A Ceia é individual ou comunitária?","Como a mesa nos une?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 5, 'Comunhão na mesa', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('d2a79e5f-dd21-4209-8223-203e78897565', NULL, 'Examine-se o homem a si mesmo e assim coma do pão e beba do cálice.', '1 Coríntios 11:28', 'Antes da Ceia, devemos nos examinar — não para nos excluir, mas para chegar com coração sincero.', 'Senhor, examina-me e purifica-me para a Tua mesa. Amém.', 'Faça um autoexame honesto diante de Deus.', '{"O que significa se examinar antes da Ceia?","Isso te afasta ou aproxima da mesa?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 6, 'Autoexame', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('0c1fa8e4-f547-4586-90b6-623b16136c75', NULL, 'A Ceia é remédio para os doentes, não prêmio para os saudáveis.', 'Lutero', 'Lutero ensinou que a Ceia não é para perfeitos — é para pecadores que precisam de Cristo.', 'Jesus, venho à Tua mesa não porque sou bom, mas porque preciso de Ti. Amém.', 'Se sente indignidade, lembre-se: a Ceia é para você!', '{"A Ceia é para perfeitos ou pecadores?","Você já se sentiu indigno de participar?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 7, 'Ceia como remédio', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('e15006c5-e926-4da1-bf23-85cb056a55ad', NULL, 'Bem-aventurados os chamados à ceia das bodas do Cordeiro.', 'Apocalipse 19:9', 'Cada Ceia aqui é antecipação da grande festa eterna com Cristo — a ceia das bodas do Cordeiro.', 'Jesus, espero a festa eterna contigo. Até lá, celebro à Tua mesa. Amém.', 'Ao participar da Ceia, pense na eternidade com Cristo.', '{"A Ceia aponta para o futuro?","Como isso muda sua participação?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 8, 'Ceia e esperança', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('4fc219b3-b4fa-47fc-9e70-d8b418f25f68', NULL, 'Que darei ao Senhor? Tomarei o cálice da salvação e invocarei o Senhor.', 'Salmo 116:12-13', 'A resposta à graça é gratidão. Tomamos o cálice com ação de graças por tudo que Cristo fez.', 'Pai, com gratidão tomo o cálice. Obrigado pela salvação. Amém.', 'Faça uma lista de gratidão antes da próxima Ceia.', '{"Você participa da Ceia com gratidão?","O que pode te ajudar a chegar com mais ação de graças?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 9, 'Gratidão à mesa', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('e5fbd3ff-8ab6-4ad5-b7b8-8a4c974d5297', NULL, 'Examinai-vos a vós mesmos se realmente estais na fé.', '2 Coríntios 13:5', 'Estamos nos preparando para participar dignamente da Ceia. Não com méritos, mas com fé sincera.', 'Senhor, prepara meu coração para a Tua mesa. Amém.', 'Prepare-se para o encontro: escreva o que a Ceia significa para você.', '{"Você está preparado para a Ceia?","O que mais aprendeu sobre a Santa Ceia?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'df47e9a4-91e0-4678-aef9-d81dc1619177', 10, 'Minha preparação para a Ceia', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('efbb09f5-5055-4855-ad5d-cbeb570322ea', NULL, 'Um novo mandamento vos dou: que vos ameis uns aos outros como eu vos amei.', 'João 13:34', 'O amor cristão não é opcional — é mandamento. E o padrão é o amor de Cristo: incondicional.', 'Jesus, ensina-me a amar como Tu amaste. Amém.', 'Demonstre amor a alguém da comunidade hoje.', '{"Como é o amor de Cristo?","Amar é sentimento ou decisão?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 1, 'Amados por Deus para amar', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('4a6c9f51-b6bc-4034-b3b7-d152fc9a142d', NULL, 'Amai-vos uns aos outros com amor fraternal; preferi-vos em honra uns aos outros.', 'Romanos 12:10', 'A Bíblia está cheia de "uns aos outros": amem-se, sirvam-se, perdoem-se, edifiquem-se. Vida cristã é relacional.', 'Senhor, ajuda-me a praticar os "uns aos outros". Amém.', 'Escolha um "uns aos outros" e pratique hoje.', '{"Quais mandamentos de \"uns aos outros\" você mais pratica?","Qual é mais difícil?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 2, 'Uns aos outros', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('0497dc63-f3e5-4745-be50-f4d2019204e9', NULL, 'Perdoai-vos mutuamente, caso alguém tenha queixa contra outrem.', 'Colossenses 3:13', 'Na comunidade, haverá ofensas. O perdão não é opcional — é o que nos mantém unidos.', 'Pai, perdoa-me e ajuda-me a perdoar meus irmãos. Amém.', 'Se há mágoa contra alguém, comece a orar por essa pessoa.', '{"É fácil perdoar? Por que não?","Há alguém que precisa do seu perdão?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 3, 'Perdão na comunidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('40f9525b-3922-4e7f-96bc-222b9c7968e5', NULL, 'Levai as cargas uns dos outros e assim cumprireis a lei de Cristo.', 'Gálatas 6:2', 'Comunhão é compartilhar peso. Quando um sofre, os outros ajudam a carregar.', 'Senhor, mostra-me quem precisa de ajuda hoje. Amém.', 'Pergunte a alguém: "Como posso te ajudar?"', '{"Você compartilha seus fardos com outros?","Ajudar os outros é fácil para você?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 4, 'Carregar os fardos', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('6393c8bc-2763-488d-ba06-791cb57a9025', NULL, 'Não vos esqueçais da hospitalidade.', 'Hebreus 13:2', 'Ser hospitaleiro é abrir coração e casa. É fazer o outro se sentir acolhido e amado.', 'Senhor, faça de mim alguém hospitaleiro. Amém.', 'Convide alguém para um café ou refeição.', '{"O que é hospitalidade cristã?","Como praticá-la no mundo de hoje?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 5, 'Hospitalidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('f5d9e085-2037-4e1f-89ae-991e1a206f03', NULL, 'Seguindo a verdade em amor, cresçamos em tudo nAquele que é a cabeça, Cristo.', 'Efésios 4:15', 'Comunhão verdadeira inclui honestidade — mas sempre com amor. Verdade sem amor machuca; amor sem verdade engana.', 'Senhor, dá-me coragem e graça para falar a verdade em amor. Amém.', 'Se precisar corrigir alguém, faça com amor.', '{"Como falar a verdade sem machucar?","Você aceita correção com humildade?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 6, 'Falar a verdade em amor', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('c8a85a08-de33-4535-8285-e26950eb832b', NULL, 'Encorajai-vos e edificai-vos uns aos outros.', '1 Tessalonicenses 5:11', 'Palavras de encorajamento são poderosas. Na comunhão cristã, levantamos uns aos outros.', 'Senhor, usa minhas palavras para edificar, não destruir. Amém.', 'Envie uma mensagem de encorajamento a alguém da comunidade.', '{"Quando foi a última vez que alguém te encorajou?","Quem precisa ouvir palavras edificantes de você?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 7, 'Encorajamento mútuo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('794017fb-4220-43dd-b957-24ac63c1bb6a', NULL, 'Esforçando-vos por preservar a unidade do Espírito no vínculo da paz.', 'Efésios 4:3-4', 'Somos diferentes, mas o Espírito nos une. Unidade não é uniformidade — é harmonia na diversidade.', 'Espírito, preserva nossa unidade na diversidade. Amém.', 'Aprecie as diferenças de alguém da comunidade.', '{"Unidade e uniformidade são a mesma coisa?","Como lidar com diferenças na igreja?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 8, 'Unidade na diversidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('3fb33bd8-ee48-4775-88e9-d8d15a0a5752', NULL, 'Se eu, o Senhor e Mestre, vos lavei os pés, também vós deveis lavar os pés uns dos outros.', 'João 13:14-15', 'Jesus serviu lavando pés. Servir é a marca do discípulo — não por obrigação, mas com alegria.', 'Jesus, dá-me coração de servo. Amém.', 'Faça algo que ninguém pede: arrume, ajude, sirva sem esperar reconhecimento.', '{"Jesus como servo te inspira?","Você serve com alegria ou obrigação?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 9, 'Servir com alegria', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('a51268a8-4e25-4c5c-a3da-408ac3528f0f', NULL, 'Como o ferro com ferro se aguça, assim o homem afia o seu companheiro.', 'Provérbios 27:17', 'A verdadeira comunhão nos melhora. Quando vivemos juntos em Cristo, somos transformados.', 'Senhor, que nossa comunhão me transforme e transforme os outros. Amém.', 'Prepare-se para o encontro: como a comunhão te mudou?', '{"Como seus irmãos te afiaram?","O que você aprendeu sobre comunhão nestas semanas?"}', '2026-02-24 21:54:46.132706+00', '2026-05-13 12:53:51.627337+00', 'a5320de3-b9ef-4ad8-aa9a-f9c818fccddb', 10, 'Comunhão que transforma', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('dad0fbdc-34ad-46a2-beaf-834ae34dc303', NULL, 'Sede santos, porque eu sou santo.', '1 Pedro 1:15-16', 'Santidade não é perfeição — é separação. Somos chamados a viver diferente porque pertencemos a Deus.', 'Deus santo, santifica-me pela Tua verdade. Amém.', 'Identifique uma área que precisa de mais santidade.', '{"O que é santidade?","É possível ser santo no mundo de hoje?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 1, 'Chamados à santidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('54d4194f-64ac-486e-949a-3d381ff85b9d', NULL, 'Vós sois o sal da terra. Vós sois a luz do mundo.', 'Mateus 5:13-14', 'Sal preserva e dá sabor. Luz ilumina e guia. Somos chamados a impactar o mundo ao nosso redor.', 'Senhor, faça-me sal e luz onde eu estiver. Amém.', 'Identifique como você pode ser sal e luz hoje.', '{"O que significa ser sal?","E ser luz?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 2, 'Sal e luz', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('fd1bbeb5-c48d-415c-a3c3-427dbbf424bb', NULL, 'Não vos conformeis com este mundo, mas transformai-vos.', 'Romanos 12:2', 'O mundo quer nos moldar. Deus quer nos transformar. A escolha é diária.', 'Senhor, transforma-me. Não quero me conformar com o mundo. Amém.', 'Em que aspectos o mundo tenta te moldar? Resista hoje.', '{"O mundo te molda ou Deus te transforma?","Onde está a pressão mais forte?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 3, 'Transformação, não conformação', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('34a3bdd5-2212-437c-81cc-c551d558ffa2', NULL, 'Quem é fiel no pouco também é fiel no muito.', 'Lucas 16:10', 'Santidade começa nos detalhes: palavras, pensamentos, hábitos. A fidelidade no pouco revela o caráter.', 'Senhor, ajuda-me a ser fiel nos detalhes. Amém.', 'Preste atenção aos pequenos hábitos hoje.', '{"Onde a santidade se manifesta no dia a dia?","Você é fiel no pouco?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 4, 'Santidade nos pequenos detalhes', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('40981d22-7148-41f1-a482-df383f912fa9', NULL, 'Bem-aventurados os puros de coração, porque verão a Deus.', 'Mateus 5:8', 'Pureza não é aparência — é o coração. Deus olha para dentro e quer nos purificar de dentro para fora.', 'Deus, purifica meu coração. Quero Te ver. Amém.', 'Examine seus pensamentos: há algo que precisa ser purificado?', '{"O que é pureza de coração?","Como cultivá-la no mundo atual?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 5, 'Pureza de coração', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('2b6d68a2-53d0-431d-a942-6e6ca5fdee50', NULL, 'Mantendo exemplar o vosso procedimento no meio dos gentios.', '1 Pedro 2:12', 'Ser santo não é ser bizarro. É viver de forma tão boa que os outros vejam Deus em nós.', 'Senhor, que minha vida diferente atraia outros a Ti. Amém.', 'Viva de forma que alguém pergunte: "Por que você é assim?"', '{"É possível ser diferente sem se isolar?","Sua vida faz as pessoas questionarem?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 6, 'Diferente sem ser estranho', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('c1d367a6-78b2-45b3-a311-2ccc70536071', NULL, 'A graça de Deus nos ensina a viver neste mundo de maneira sóbria, justa e piedosa.', 'Tito 2:11-12', 'Não é esforço — é graça. A mesma graça que salva, ensina a viver em santidade.', 'Graça de Deus, ensina-me a viver de forma que Te honre. Amém.', 'Descansar na graça não é passividade. Peça força para viver bem.', '{"Santidade vem por esforço ou graça?","Como a graça produz santidade?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 7, 'Santidade e graça', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('78f3fd80-2650-45eb-bb54-6f75f235329a', NULL, 'Para que vos torneis irrepreensíveis, resplandecendo como luzeiros no mundo.', 'Filipenses 2:15', 'Nossa santidade influencia. Quando vivemos para Cristo, brilhamos como estrelas na escuridão.', 'Senhor, que eu resplandeça como luz no meio da escuridão. Amém.', 'Seja uma influência positiva para alguém hoje.', '{"Sua vida influencia positivamente os outros?","Quem é influenciado por você?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 8, 'Influência positiva', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('17e408dc-0bfc-4b21-843d-094cc8e297fa', NULL, 'Daniel resolveu não se contaminar.', 'Daniel 1:8', 'Daniel viveu num ambiente hostil à fé e escolheu ser fiel. Nós também podemos resistir à pressão.', 'Senhor, como Daniel, resolvo não me contaminar. Dá-me coragem. Amém.', 'Identifique uma pressão social que desafia sua fé e resista.', '{"Que pressões sociais desafiam sua santidade?","Como Daniel te inspira?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 9, 'Resistindo à pressão', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b8793589-034b-4e18-a17a-651625d7001c', NULL, 'Fazei tudo para a glória de Deus.', '1 Coríntios 10:31', 'Santidade resume-se nisso: fazer TUDO — comer, beber, estudar, jogar — para a glória de Deus.', 'Senhor, que tudo que eu faça Te glorifique. Amém.', 'Prepare-se para o encontro: como sua vida pode glorificar mais a Deus?', '{"É possível glorificar a Deus em tudo?","O que precisa mudar na sua rotina?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '53e3484c-7b8c-4efe-ba9c-c90f7796224f', 10, 'Vivendo para a glória de Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('936a9f47-cda4-4876-94cf-fec767c61284', NULL, 'Do Senhor é a terra e tudo o que nela se contém.', 'Salmo 24:1', 'Nada é realmente nosso — somos administradores do que Deus nos confiou.', 'Senhor, reconheço que tudo é Teu. Ajuda-me a administrar bem. Amém.', 'Liste o que Deus te confiou: tempo, talentos, recursos.', '{"Você sente que suas coisas são suas ou de Deus?","Isso muda como as usa?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 1, 'Tudo pertence a Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('7e91457e-fb8f-4a7a-b2fc-ca7baf7d8322', NULL, 'Remindo o tempo, porque os dias são maus.', 'Efésios 5:15-16', 'O tempo passa e não volta. Usar bem o tempo é sabedoria — e honra a Deus.', 'Senhor, ajuda-me a usar meu tempo com sabedoria. Amém.', 'Analise como você gastou seu tempo ontem. O que mudaria?', '{"Como você gasta seu tempo?","Há espaço para Deus na sua agenda?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 2, 'Tempo: o recurso mais precioso', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('f84b2644-a748-4bb9-b4aa-92948ced0e56', NULL, 'Deu a cada um segundo a sua própria capacidade.', 'Mateus 25:15', 'Deus deu talentos diferentes a cada um. Não enterrar, mas investir é a resposta correta.', 'Senhor, mostra-me meus talentos e como usá-los. Amém.', 'Identifique 3 talentos que Deus te deu.', '{"Quais são seus talentos?","Você os está usando ou enterrando?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 3, 'Talento: dom de Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('087f2879-91ba-4202-9c15-93d890349897', NULL, 'Deus ama a quem dá com alegria.', '2 Coríntios 9:7', 'Generosidade não é obrigação — é alegria. Quando entendemos que tudo é de Deus, dar é natural.', 'Pai, faça-me generoso como Tu és. Amém.', 'Pratique generosidade hoje: dê algo (tempo, dinheiro, atenção).', '{"Você é generoso?","Dar com alegria é possível para você?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 4, 'Tesouro: generosidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('92ef308c-8e34-429f-8a8f-6465058b0eee', NULL, 'Quem é fiel no pouco também é fiel no muito.', 'Lucas 16:10', 'Mordomia começa com pouco. Fidelidade nas pequenas coisas prepara para responsabilidades maiores.', 'Senhor, ajuda-me a ser fiel no pouco que tenho. Amém.', 'Cuide de algo pequeno com excelência hoje.', '{"Você é fiel nas coisas pequenas?","Como isso prepara para o muito?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 5, 'Mordomia na prática', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('cc599ca1-e0ab-4a5e-a8cb-6c8aaf89cafd', NULL, 'Levantou-se de madrugada e foi orar.', 'Marcos 1:35', 'Se Jesus separava tempo para Deus, quanto mais nós? O devocional diário é investimento de tempo.', 'Senhor, priorizo meu tempo com Ti. Amém.', 'Separe um horário fixo para Deus amanhã.', '{"Você tem um horário reservado para Deus?","O que te impede?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 6, 'Tempo para Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('526d5290-c5aa-4897-8b0f-63b7f9cf3bd1', NULL, 'Tudo quanto fizerdes, fazei-o de todo o coração como para o Senhor.', 'Colossenses 3:23', 'Usar talentos para servir é adoração. Quando servimos de coração, servimos a Deus.', 'Senhor, uso meus talentos para Te servir de todo coração. Amém.', 'Use um talento seu para abençoar alguém esta semana.', '{"Seus talentos servem a Deus ou só a você?","Como servir de todo coração?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 7, 'Servir com talento', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('e0d77482-9b16-4cd6-8810-6b3040e1ddd8', NULL, 'O amor ao dinheiro é raiz de todos os males.', '1 Timóteo 6:10', 'O dinheiro não é mau — o amor ao dinheiro sim. Quando o tesouro domina, perdemos o foco.', 'Senhor, livra-me da ganância. Que meu tesouro esteja em Ti. Amém.', 'Reflita: o dinheiro ocupa que lugar na sua vida?', '{"Dinheiro é bom ou mau?","Como evitar que ele domine sua vida?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 8, 'O perigo da ganância', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('be71060f-5efb-43d2-9b7d-949fff7bed4d', NULL, 'Ajuntai tesouros no céu.', 'Mateus 6:19-20', 'Investimentos terrenos acabam. Os celestes permanecem. A pergunta é: onde está seu coração?', 'Senhor, ajuda-me a investir no eterno. Amém.', 'Faça algo eterno hoje: ame, sirva, ensine, ore.', '{"O que são tesouros no céu?","Onde está seu coração?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 9, 'Investindo no eterno', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('d3f632fa-0606-4aeb-8d70-3fa17899d6ff', NULL, 'Muito bem, servo bom e fiel; sobre o pouco foste fiel, sobre o muito te colocarei.', 'Mateus 25:21', 'A recompensa do mordomo fiel é mais responsabilidade — e a aprovação do Mestre.', 'Senhor, quero ouvir: "Muito bem, servo bom e fiel." Amém.', 'Prepare-se para o encontro: como será um mordomo melhor?', '{"Você quer ouvir essas palavras de Jesus?","O que precisa mudar para ser mais fiel?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', '72552eda-8237-402a-acc1-8aec49830c48', 10, 'Mordomo fiel', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('1bb7d1ef-4e10-415b-a073-86e8a193967d', NULL, 'Ide, fazei discípulos de todas as nações.', 'Mateus 28:19-20', 'Compartilhar a fé não é opcional — é a última ordem de Jesus. Todos somos comissionados.', 'Jesus, comissiona-me. Dá-me coragem para falar de Ti. Amém.', 'Ore por alguém que precisa conhecer Jesus.', '{"A Grande Comissão é para todos ou só para pastores?","Quem precisa ouvir sobre Jesus ao seu redor?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 1, 'A Grande Comissão', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('2bedbbc0-50eb-47a5-9344-6e10fca3ba2c', NULL, 'Não me envergonho do Evangelho.', 'Romanos 1:16', 'É natural ter vergonha — mas o Evangelho é poder de Deus. Não precisamos ter medo de compartilhá-lo.', 'Senhor, tira a vergonha e dá-me ousadia. Amém.', 'Identifique o que te dá vergonha de falar de Jesus e ore sobre isso.', '{"Você tem vergonha do Evangelho?","O que causa essa vergonha?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 3, 'Sem vergonha', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('649d0550-60a9-4f0e-9f28-7c160bd151ee', NULL, 'Estai sempre preparados para responder a todo aquele que vos pedir razão da esperança que há em vós.', '1 Pedro 3:15', 'Evangelismo natural começa com uma vida que gera perguntas. Esteja pronto para responder com mansidão.', 'Senhor, prepara-me para dar razão da minha esperança. Amém.', 'Se alguém perguntasse "por que você crê?", o que responderia?', '{"Você está preparado para falar da sua fé?","O que te dá esperança?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 4, 'Sempre prontos', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('8961f08f-d845-4033-a529-34733ab14761', NULL, 'Se não tiver amor, nada serei.', '1 Coríntios 13:1', 'O melhor evangelismo é o amor. Palavras sem amor são ruído. Ame primeiro, fale depois.', 'Senhor, que meu evangelismo seja movido por amor. Amém.', 'Ame alguém de forma prática antes de falar de Jesus.', '{"Evangelismo sem amor funciona?","Como o amor abre portas?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 5, 'Amor como método', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('551d1885-066d-4289-b12c-d87fb3a9c3ba', NULL, 'Todo homem seja pronto para ouvir, tardio para falar.', 'Tiago 1:19', 'Bons evangelistas são bons ouvintes. Ouvir a história do outro é o caminho para compartilhar a sua.', 'Senhor, ensina-me a ouvir antes de falar. Amém.', 'Em uma conversa hoje, ouça mais do que fale.', '{"Você ouve mais ou fala mais?","Como ouvir ajuda no evangelismo?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 6, 'Ouvir antes de falar', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('95217d0e-fcfe-434c-8956-19e38ac8638e', NULL, 'Assim brilhe a vossa luz diante dos homens, para que vejam as vossas boas obras.', 'Mateus 5:16', 'Seu estilo de vida é o evangelismo mais poderoso. Quando sua vida é coerente, suas palavras têm peso.', 'Senhor, que minha vida fale mais que minhas palavras. Amém.', 'Faça uma boa obra visível hoje.', '{"Sua vida é coerente com sua fé?","As pessoas veem Jesus em você?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 7, 'Viva o que prega', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('441648c3-7fd3-46ce-b4c8-523b18f61de3', NULL, 'Eu plantei, Apolo regou, mas Deus é quem deu o crescimento.', '1 Coríntios 3:6', 'Tira a pressão: a conversão não depende de você. Você planta e rega; Deus faz crescer.', 'Pai, planto sementes. Tu fazes crescer. Amém.', 'Plante uma semente hoje — uma conversa, uma oração, um ato de bondade.', '{"A conversão depende de nós ou de Deus?","Isso alivia ou aumenta a pressão?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 8, 'Não é você quem converte', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('5f70437a-67a7-440d-9dfb-ac57a11ed6bd', NULL, 'Ficaram todos cheios do Espírito Santo e, com intrepidez, anunciavam a palavra.', 'Atos 4:31', 'Os discípulos tinham medo, mas o Espírito deu coragem. O mesmo Espírito habita em você.', 'Espírito Santo, enche-me de coragem para falar de Jesus. Amém.', 'Peça coragem ao Espírito antes de uma conversa importante.', '{"De onde vem a coragem para evangelizar?","Você pede ajuda ao Espírito?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 9, 'Coragem do Espírito', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('4134fec2-5b74-4e2f-b416-280fbcad6bf6', NULL, 'Vai para tua casa e conta-lhes tudo o que o Senhor te fez.', 'Marcos 5:19', 'Seu testemunho é único e poderoso. Ninguém pode contestar o que Deus fez em sua vida.', 'Senhor, uso minha história para Tua glória. Amém.', 'Prepare-se para o encontro: escreva seu testemunho completo para compartilhar.', '{"Qual é o testemunho que só você pode dar?","Está pronto para compartilhá-lo?"}', '2026-02-24 21:56:14.137121+00', '2026-05-13 12:53:51.627337+00', 'aafeed77-5e14-4a50-8f72-0be595b9d5cd', 10, 'Meu testemunho pessoal', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('5e859f9e-3016-4482-96fd-1cae2e76f966', NULL, '“Pois todos pecaram e estão destituídos da glória de Deus.”', 'Romanos 3.23', 'A Bíblia diz que todos pecaram. Isso significa que todos nós falhamos, erramos e nos afastamos de Deus. O pecado não é apenas fazer coisas erradas, mas também é viver longe de Deus, confiar mais em nós mesmos do que nele e tentar viver sem Ele.
INSERT INTO public.devotional_content (id, activity_id, bible_text, bible_reference, reflection, prayer, practice, questions, created_at, updated_at, lesson_id, day_number, title, worship_song_id, church_id)
VALUES
('25caca42-bf81-4916-ab68-b36a719a1404', NULL, 'Por essa razão, torno a lembrar-lhe que mantenha viva a chama do dom de Deus que está em você.', '2 Timóteo 1:6', 'Dons precisam ser desenvolvidos. Um dom não cultivado se enfraquece. Paulo lembrou Timóteo de "reavivar" o dom — isso exige prática e dedicação.', 'Senhor, ajuda-me a não negligenciar os dons que me deste. Quero desenvolvê-los para Tua glória. Amém.', 'Escolha um dom que você acredita ter e invista 15 minutos praticando-o hoje.', '{"O que significa \"manter viva a chama\" dos dons?","Como podemos desenvolver nossos dons espirituais?"}', '2026-02-24 22:05:07.819294+00', '2026-05-13 12:53:51.627337+00', 'faddbfea-4925-4a89-920b-7da2905c747f', 6, 'Desenvolvendo seus dons', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('80d0ce0f-5c91-4b25-bf3e-1d80a3b877dd', NULL, 'Pois somos criação de Deus realizada em Cristo Jesus para fazermos boas obras, as quais Deus preparou antes para nós as praticarmos.', 'Efésios 2:10', 'Seus dons apontam para seu chamado. Deus preparou obras específicas para você — e Ele te equipou com os dons necessários para realizá-las.', 'Senhor, revela o chamado que preparaste para mim. Quero cumprir Teu propósito. Amém.', 'Escreva sobre como seus dons podem se conectar com seu chamado pessoal.', '{"Qual a relação entre dons e chamado?","Como seus dons podem indicar o propósito de Deus para você?"}', '2026-02-24 22:05:07.819294+00', '2026-05-13 12:53:51.627337+00', 'faddbfea-4925-4a89-920b-7da2905c747f', 7, 'Dons e chamado pessoal', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('82127b92-6845-45c4-af58-3eef08a7b675', NULL, 'Ainda que eu fale as línguas dos homens e dos anjos, se não tiver amor, serei como o sino que ressoa.', '1 Coríntios 13:1-3', 'Todos os dons sem amor são vazios. O amor é o motor e a motivação de todo serviço cristão. Sem ele, os dons se tornam barulho.', 'Senhor, que o amor seja a motivação de tudo que eu faço com meus dons. Amém.', 'Releia 1 Coríntios 13 inteiro e avalie se o amor guia seu serviço.', '{"Por que o amor é chamado de \"o maior\"?","Como servir com amor muda a forma como usamos nossos dons?"}', '2026-02-24 22:05:07.819294+00', '2026-05-13 12:53:51.627337+00', 'faddbfea-4925-4a89-920b-7da2905c747f', 8, 'O maior dom: amor', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('6b5ecafa-34d0-4d31-b178-c06d938e12d9', NULL, 'Depois disso, derramarei o meu Espírito sobre todos os povos. Os seus filhos e as suas filhas profetizarão.', 'Joel 2:28', 'Deus derrama Seu Espírito sobre jovens e velhos. Sua idade não limita seus dons. Deus quer usar adolescentes de forma poderosa na Sua obra.', 'Senhor, usa-me mesmo sendo jovem. Derrama Teu Espírito e capacita-me para servir. Amém.', 'Pense em como Deus pode usar você agora, nesta fase da vida.', '{"Deus pode usar adolescentes de forma significativa?","Como o Espírito capacita jovens para servir?"}', '2026-02-24 22:05:07.819294+00', '2026-05-13 12:53:51.627337+00', 'faddbfea-4925-4a89-920b-7da2905c747f', 9, 'Dons para todas as gerações', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('be51b7c4-d4ce-4ba2-8965-5fbd1b1c0ccf', NULL, 'A todo aquele que tem, mais será dado, e terá em abundância. Mas ao que não tem, até o que tem lhe será tirado.', 'Mateus 25:14-30', 'A parábola dos talentos nos ensina que Deus espera que usemos o que recebemos. Enterrar nossos dons por medo ou preguiça desagrada ao Senhor.', 'Senhor, não quero enterrar o que me deste. Dá-me coragem para colocar meus dons em ação. Amém.', 'Prepare uma reflexão sobre seus dons para compartilhar no encontro.', '{"O que a parábola dos talentos ensina sobre dons?","O que você vai fazer com os dons que descobriu?"}', '2026-02-24 22:05:07.819294+00', '2026-05-13 12:53:51.627337+00', 'faddbfea-4925-4a89-920b-7da2905c747f', 10, 'Colocando os dons em ação', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('9ed4e55b-4b51-466e-af8c-c07fc5b1001a', NULL, 'Pois nem mesmo o Filho do homem veio para ser servido, mas para servir e dar a sua vida em resgate por muitos.', 'Marcos 10:45', 'Jesus, o Rei do universo, veio como servo. Se Ele serviu, quanto mais devemos nós. Serviço não é opção — é a marca do discípulo.', 'Jesus, ensina-me a servir como Tu serviste — com humildade e amor sacrificial. Amém.', 'Faça algo para servir alguém hoje sem esperar reconhecimento.', '{"O que significa Jesus ter vindo \"para servir\"?","Servir é difícil para você? Por quê?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 1, 'Chamados para servir', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('95bbdf9c-ef35-4513-89d3-f49473e5e6fb', NULL, 'Pois sou eu que conheço os planos que tenho para vocês, planos de fazê-los prosperar e não de lhes causar dano, planos de dar-lhes esperança e um futuro.', 'Jeremias 29:11', 'Vocação não é só profissão — é o propósito de Deus para toda a sua vida. Onde seus dons encontram as necessidades do mundo, ali está seu chamado.', 'Senhor, revela os planos que tens para mim. Quero estar onde Tu me queres. Amém.', 'Escreva 3 coisas que você ama fazer e como elas podem servir ao próximo.', '{"Qual a diferença entre profissão e vocação?","Como descobrir onde Deus quer que você sirva?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 2, 'Vocação: onde Deus me quer', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('0ba05083-7fd8-4054-b7f6-d63e5caadfdf', NULL, 'Tudo o que fizerem, façam de todo o coração, como para o Senhor, e não para os homens.', 'Colossenses 3:23-24', 'Serviço cristão não é só na igreja. Estudar, trabalhar, ajudar em casa — tudo pode ser feito como adoração a Deus quando feito de coração.', 'Senhor, que cada tarefa do meu dia seja um ato de adoração a Ti. Amém.', 'Faça suas tarefas diárias hoje com a consciência de que está fazendo "para o Senhor".', '{"Como o cotidiano pode ser um ato de adoração?","O que muda quando fazemos tudo \"para o Senhor\"?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 3, 'Serviço no cotidiano', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('7a3f3da0-ada8-41ee-866c-1e942144e7a4', NULL, 'Daniel distinguia-se entre os outros, pois nele havia um espírito extraordinário.', 'Daniel 6:3', 'Daniel se destacou pela excelência no serviço. Cristãos devem buscar fazer o melhor — não por perfeccionismo, mas por amor a Deus.', 'Senhor, ajuda-me a fazer tudo com excelência para Tua glória. Amém.', 'Escolha uma tarefa que você normalmente faz "de qualquer jeito" e faça com excelência hoje.', '{"O que diferenciava Daniel dos outros?","Como a excelência no serviço glorifica a Deus?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 4, 'Servindo com excelência', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('cd2f949b-d4ea-46b6-a696-42d978ea9632', NULL, 'Pois bem, se eu, sendo Senhor e Mestre de vocês, lavei os seus pés, vocês também devem lavar os pés uns dos outros.', 'João 13:14-15', 'Lavar pés era trabalho de escravos. Jesus fez isso para nos ensinar que nenhum serviço é degradante quando feito com amor. Humildade é a marca do servo.', 'Jesus, dá-me um coração de servo. Que eu não considere nenhum serviço pequeno demais. Amém.', 'Faça uma tarefa humilde que você normalmente evitaria.', '{"Por que Jesus lavou os pés dos discípulos?","Que tipos de serviço você considera \"abaixo\" de você?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 5, 'Lavar pés: humildade no serviço', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('82c3ea3e-71b2-4724-a258-998cee5e3a5a', NULL, 'Busquem, pois, em primeiro lugar o Reino de Deus e a sua justiça, e todas essas coisas lhes serão acrescentadas.', 'Mateus 6:33', 'Quando colocamos Deus em primeiro lugar, Ele ordena todo o resto — inclusive nossa vocação. Buscar o Reino significa alinhar nossos planos com os Dele.', 'Senhor, que Teu Reino seja minha prioridade. Alinha meus planos com os Teus. Amém.', 'Ore especificamente sobre seu futuro profissional, entregando-o a Deus.', '{"Como buscar o Reino afeta nossas escolhas de carreira?","Seus planos de futuro incluem servir a Deus?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 6, 'Vocação e reino de Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('78292b10-3b5a-46b2-9b40-b0d7c3714720', NULL, 'Portanto, quer vocês comam, quer bebam, quer façam qualquer outra coisa, façam tudo para a glória de Deus.', '1 Coríntios 10:31', 'Não existe área secular e sagrada para Deus. Um cristão na medicina, na arte, na tecnologia ou na agricultura pode glorificar a Deus tanto quanto um pastor.', 'Senhor, obrigado porque posso Te glorificar em qualquer área. Abençoa meus estudos e meu trabalho. Amém.', 'Pense na sua área de interesse e como ela pode ser usada para glória de Deus.', '{"Existe diferença entre trabalho \"secular\" e \"sagrado\"?","Como sua área de interesse pode servir ao Reino?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 7, 'Servindo em todas as áreas', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('3c1eedcb-4018-4f71-990d-759f0a001cd8', NULL, 'Pois o amor de Cristo nos constrange.', '2 Coríntios 5:14', 'A motivação certa para servir não é culpa, obrigação ou busca de aprovação — é o amor de Cristo. Quando entendemos o quanto fomos amados, servir se torna natural.', 'Jesus, que Teu amor seja a motivação de todo meu serviço. Amém.', 'Avalie: por que você serve? Por obrigação, culpa ou amor?', '{"Qual deve ser a motivação do serviço cristão?","Como o amor de Cristo nos constrange a servir?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 8, 'Motivação para servir', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('0561a70b-ad38-460d-a045-4c401ae0a237', NULL, 'Contaremos à próxima geração os feitos dignos de louvor do Senhor, o seu poder e as maravilhas que fez.', 'Salmo 78:4,6-7', 'Parte do serviço cristão é investir nas próximas gerações. O que você aprende e vive agora pode abençoar pessoas que ainda nem nasceram.', 'Senhor, que minha vida hoje seja semente de bênção para as gerações futuras. Amém.', 'Pense em alguém mais jovem que você pode influenciar positivamente.', '{"Por que é importante investir nas próximas gerações?","Como você pode ser uma bênção para quem vem depois de você?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 9, 'Servindo as gerações futuras', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('ab96526f-714b-499b-9e44-6e112a8f42f1', NULL, 'Então ouvi a voz do Senhor, conclamando: "Quem enviarei? Quem irá por nós?" E eu respondi: "Eis-me aqui. Envia-me!"', 'Isaías 6:8', 'Deus ainda pergunta: "Quem irá?" A resposta não exige perfeição — exige disposição. Diga "sim" e Deus fará o resto.', 'Senhor, eis-me aqui. Envia-me! Usa-me onde Tu quiseres. Amém.', 'Prepare uma reflexão sobre serviço e vocação para compartilhar no encontro.', '{"O que significa dizer \"Eis-me aqui\" a Deus?","O que você aprendeu sobre serviço e vocação nestas semanas?"}', '2026-02-24 22:05:55.024207+00', '2026-05-13 12:53:51.627337+00', 'c868695c-b915-43b1-9247-9c6160fa6cf3', 10, 'Minha resposta ao chamado', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('ab5190a7-2132-4606-a94c-f10d2d28b7ea', NULL, 'Neste mundo vocês terão aflições. Contudo, tenham ânimo! Eu venci o mundo.', 'João 16:33', 'Jesus não prometeu vida sem sofrimento — prometeu presença no sofrimento. Aflições são inevitáveis, mas não são a palavra final.', 'Jesus, obrigado por vencer o mundo. No meio do sofrimento, lembra-me da Tua vitória. Amém.', 'Escreva sobre um momento difícil em que sentiu a presença de Deus.', '{"Por que Jesus diz que teremos aflições?","Como a vitória de Cristo sobre o mundo traz esperança?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 1, 'Por que sofremos?', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('37e82de4-f5a3-48b0-bd51-9f4e346e6b27', NULL, 'Imediatamente o pai do menino exclamou: "Creio, ajuda-me na minha incredulidade!"', 'Marcos 9:24', 'Ter dúvidas não significa falta de fé — significa que sua fé está viva e buscando respostas. Deus não se ofende com perguntas honestas.', 'Senhor, creio! Mas ajuda-me nas minhas dúvidas. Fortalece minha fé frágil. Amém.', 'Escreva uma dúvida que você tem sobre a fé e pesquise na Bíblia uma resposta.', '{"Por que ter dúvidas não é pecado?","Você tem alguma dúvida sobre sua fé? Qual?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 2, 'Dúvidas não são pecado', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('5ea27d47-7288-4246-a637-92aed55cf727', NULL, 'O Senhor está perto dos que têm o coração quebrantado e salva os de espírito abatido.', 'Salmo 34:18', 'Deus não observa seu sofrimento de longe — Ele está perto. Quanto mais quebrantado o coração, mais íntima é a presença de Deus.', 'Senhor, obrigado por estares perto quando meu coração dói. Consola-me com Tua presença. Amém.', 'Ore por alguém que está sofrendo e envie uma mensagem de encorajamento.', '{"O que significa Deus estar \"perto\" dos quebrantados?","Você já experimentou a proximidade de Deus no sofrimento?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 3, 'Deus no sofrimento', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('b1637725-b790-49ff-9cd5-4591981d5880', NULL, 'Nos gloriamos nas tribulações, porque sabemos que a tribulação produz perseverança; a perseverança, um caráter aprovado; e o caráter aprovado, esperança.', 'Romanos 5:3-5', 'Sofrimento, quando vivido com fé, nos transforma. Não é punição — é processo. Deus usa o que dói para produzir o que é bom.', 'Senhor, usa minhas tribulações para produzir caráter e esperança em mim. Amém.', 'Reflita: algum sofrimento passado produziu algo bom na sua vida?', '{"Como o sofrimento pode produzir esperança?","Qual o processo descrito por Paulo em Romanos 5:3-5?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 4, 'O sofrimento que produz esperança', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('e7447c3a-fc83-42eb-aadd-1423f151115d', NULL, 'Até quando, Senhor? Para sempre Te esquecerás de mim? Até quando esconderás de mim o Teu rosto?', 'Salmo 13:1-2', 'O salmista sentiu que Deus estava longe — e mesmo assim continuou orando. A honestidade com Deus no sofrimento é fé, não desrespeito.', 'Senhor, mesmo quando Te pareço distante, sei que estás aqui. Não me abandones. Amém.', 'Se você se sente distante de Deus, seja honesto em oração — como o salmista.', '{"É errado sentir que Deus está distante?","Como continuar orando quando Deus parece em silêncio?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 5, 'Quando Deus parece distante', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('a4ed3789-d94e-47fa-b1b1-95e3eeae6c70', NULL, 'A minha graça é suficiente para você, pois o meu poder se aperfeiçoa na fraqueza.', '2 Coríntios 12:9-10', 'Paulo aprendeu que suas fraquezas eram o palco perfeito para o poder de Deus. Quando somos fracos, Deus é forte em nós.', 'Senhor, obrigado porque Teu poder se aperfeiçoa na minha fraqueza. Uso minha fraqueza como altar. Amém.', 'Identifique uma fraqueza e entregue-a a Deus pedindo Sua força.', '{"O que Paulo quis dizer com \"gloriar-se nas fraquezas\"?","Como a graça de Deus é suficiente no sofrimento?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 6, 'Força na fraqueza', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('c421b6bd-2f7b-4dba-9c2f-cf045fb3f5c8', NULL, 'Por que você está assim tão triste, ó minha alma? Por que está assim tão perturbada dentro de mim? Ponha a sua esperança em Deus!', 'Salmo 42:5', 'A Bíblia tem um livro inteiro de lamentações. Chorar, questionar e expressar dor diante de Deus é uma forma legítima de oração.', 'Senhor, recebe minha dor como oração. Transforma meu lamento em esperança. Amém.', 'Escreva um salmo pessoal de lamentação, sendo honesto com Deus sobre sua dor.', '{"A lamentação é uma forma válida de oração?","Como transformar lamento em esperança?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 7, 'Lamentação como oração', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('99d0f2b7-949d-4a94-84a8-12e19c2d262b', NULL, 'Levem os fardos pesados uns dos outros e, assim, cumpram a lei de Cristo.', 'Gálatas 6:2', 'Sofrimento não foi feito para ser enfrentado sozinho. A Igreja é uma comunidade de cura onde carregamos os fardos uns dos outros.', 'Senhor, obrigado por pessoas que me ajudam. Que eu também carregue os fardos dos outros. Amém.', 'Ofereça ajuda a alguém que está passando por dificuldades.', '{"O que significa \"carregar os fardos\" uns dos outros?","Por que é difícil pedir ajuda no sofrimento?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 8, 'Ajuda mútua no sofrimento', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('73c5d7a5-4dd8-4b2f-8e8a-c8f5c70c5360', NULL, 'Confie no Senhor de todo o seu coração e não se apoie em seu próprio entendimento.', 'Provérbios 3:5-6', 'Nem sempre vamos entender por que sofremos. Mas podemos confiar em Quem está no controle. Confiança não exige compreensão — exige fé.', 'Senhor, mesmo sem entender, eu confio em Ti. Tu és bom e Teus planos são perfeitos. Amém.', 'Entregue a Deus uma situação que você não consegue entender.', '{"É possível confiar sem entender?","Como você lida quando a vida não faz sentido?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 9, 'Confiar sem entender', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('a46f36a4-fddc-4992-ad34-9fbc0976031e', NULL, 'Sabemos que Deus age em todas as coisas para o bem daqueles que O amam.', 'Romanos 8:28', 'A promessa não é que tudo será bom, mas que Deus trabalha em tudo para o bem. Ele não desperdiça dor — Ele a redime.', 'Senhor, obrigado porque nada é desperdiçado nas Tuas mãos. Trabalha em tudo para o meu bem. Amém.', 'Prepare uma reflexão sobre sofrimento e fé para compartilhar no encontro.', '{"O que significa Deus agir \"em todas as coisas para o bem\"?","O que você aprendeu sobre sofrimento e fé nestas semanas?"}', '2026-02-24 22:06:39.36706+00', '2026-05-13 12:53:51.627337+00', 'eef65267-d505-446b-a34e-10d473f484d0', 10, 'Esperança que não decepciona', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('45cbde8d-5ee0-4712-96cc-f3a4781a38d4', NULL, 'Eu o instruirei e o ensinarei no caminho que você deve seguir; eu o aconselharei e cuidarei de você.', 'Salmo 32:8', 'Deus não nos deixa às cegas. Ele promete guiar, instruir e aconselhar. A questão não é se Deus tem um plano, mas se estamos dispostos a ouvir.', 'Senhor, instrui-me no caminho. Estou disposto a seguir Tua direção. Amém.', 'Ore pedindo direção para uma decisão que você precisa tomar.', '{"Deus tem um plano específico para cada pessoa?","Como você pode se posicionar para ouvir a voz de Deus?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 1, 'Deus tem um plano', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('e31c1d44-15b1-4b3f-837b-c2a4ceac71cb', NULL, 'A Tua palavra é lâmpada que ilumina os meus passos e luz que clareia o meu caminho.', 'Salmo 119:105', 'A Bíblia é o GPS espiritual. Deus nunca nos guiará contra o que está escrito na Sua Palavra. Toda decisão deve ser filtrada pela Escritura.', 'Senhor, que Tua Palavra ilumine cada decisão que eu preciso tomar. Amém.', 'Antes de tomar uma decisão, busque um versículo que se aplique à situação.', '{"Por que a Bíblia é essencial para discernir a vontade de Deus?","Deus pode nos guiar contra o que a Bíblia ensina?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 2, 'A Palavra como guia', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('f45bc5ae-00a1-4c7b-8071-a72671bc263b', NULL, 'O Senhor veio, parou ali e chamou como das outras vezes: "Samuel! Samuel!" E Samuel respondeu: "Fala, pois o Teu servo está ouvindo."', '1 Samuel 3:10', 'Oração não é só falar — é ouvir. Deus fala, mas muitas vezes estamos barulhentos demais para ouvir. Quietude e disposição são essenciais.', 'Senhor, fala, pois Teu servo está ouvindo. Aquieta meu coração para Te ouvir. Amém.', 'Dedique 10 minutos em silêncio ouvindo Deus após orar.', '{"Como Deus fala conosco hoje?","Qual a importância do silêncio na busca pela vontade de Deus?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 3, 'Oração e escuta', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('aa9e4381-32aa-46db-9cef-fd51b51b5030', NULL, 'Os planos fracassam por falta de conselho, mas são bem-sucedidos quando há muitos conselheiros.', 'Provérbios 15:22', 'Deus usa pessoas para nos orientar. Pastores, pais, mentores — conselheiros sábios são instrumentos de Deus para nos guiar.', 'Senhor, dá-me humildade para buscar conselho e sabedoria para discernir. Amém.', 'Procure uma pessoa de confiança e peça conselho sobre uma decisão.', '{"Por que o conselho de outros é importante?","Quem são seus conselheiros de confiança?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 4, 'Conselho sábio', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('4f2fb00d-5930-4a44-bb56-56c847ab727a', NULL, 'Que a paz de Cristo seja o juiz em seus corações.', 'Colossenses 3:15', 'A paz interior é um dos sinais da vontade de Deus. Se uma decisão traz ansiedade constante, pode ser sinal de que não é o caminho certo.', 'Senhor, que Tua paz confirme ou redirecione minhas decisões. Amém.', 'Avalie: suas decisões recentes trouxeram paz ou ansiedade?', '{"Como a paz pode ser sinal da vontade de Deus?","Toda ansiedade significa que estamos fora da vontade de Deus?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 5, 'Paz como confirmação', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('963d86c7-8606-40ed-ab78-5f300a070cf4', NULL, 'Paulo e seus companheiros viajaram pela região da Frígia e da Galácia, tendo sido impedidos pelo Espírito Santo de pregar a palavra na província da Ásia.', 'Atos 16:6-10', 'Deus abre e fecha portas. Às vezes, uma porta fechada é tão direcionadora quanto uma aberta. Circunstâncias são instrumentos de Deus.', 'Senhor, ajuda-me a ver Tua mão nas circunstâncias — tanto nas portas abertas quanto nas fechadas. Amém.', 'Reflita sobre portas que se fecharam na sua vida e como isso te redirecionou.', '{"Portas fechadas podem ser vontade de Deus?","Como discernir entre obstáculo e redirecionamento?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 6, 'Circunstâncias e providência', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('bf1cf151-3d2c-4228-a142-f3b008f14ced', NULL, 'Se algum de vocês tem falta de sabedoria, peça-a a Deus, que a todos dá livremente, de boa vontade; e lhe será concedida.', 'Tiago 1:5', 'Deus promete dar sabedoria a quem pede. Não é preciso adivinhar — basta pedir com fé e Deus concederá discernimento.', 'Senhor, concede-me sabedoria. Preciso de discernimento para as decisões da minha vida. Amém.', 'Ore especificamente pedindo sabedoria antes de uma decisão.', '{"Como Deus concede sabedoria?","Qual decisão na sua vida exige sabedoria agora?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 7, 'Sabedoria para decidir', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('8d020fc3-61fe-48ea-b85c-0b507a5632af', NULL, 'Quem é fiel no pouco, também é fiel no muito.', 'Lucas 16:10', 'Muitas vezes queremos saber o grande plano de Deus, mas Ele nos chama a ser fiéis no passo seguinte. Obediência diária revela o caminho.', 'Senhor, ajuda-me a ser fiel no pequeno enquanto espero pelo grande. Amém.', 'Identifique um "próximo passo" que Deus já mostrou e obedeça hoje.', '{"Por que Deus revela Sua vontade aos poucos?","O que significa ser fiel no pouco?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 8, 'Obediência aos poucos', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('26211e8b-0f13-4021-9e63-e4c75e6311bb', NULL, 'Quem entre vocês teme o Senhor e obedece à voz do Seu servo? Aquele que anda nas trevas, sem nenhuma luz, confie no nome do Senhor e apoie-se em seu Deus.', 'Isaías 50:10', 'Às vezes, mesmo buscando, não há clareza. Nesses momentos, continue fiel ao que já sabe e confie que Deus está trabalhando no que você não vê.', 'Senhor, mesmo sem clareza, eu confio em Ti. Guia-me mesmo quando não enxergo o caminho. Amém.', 'Se está em dúvida, continue fazendo o que é certo enquanto espera clareza.', '{"O que fazer quando a vontade de Deus não está clara?","Como manter a fé na incerteza?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 9, 'Quando não há clareza', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('13cefd61-bf90-4204-a38d-d25f1dd8b737', NULL, 'Consagre ao Senhor tudo o que você faz, e os seus planos serão bem-sucedidos. O coração do homem planeja o seu caminho, mas o Senhor lhe dirige os passos.', 'Provérbios 16:3,9', 'Planejar é bom, mas entregar os planos a Deus é melhor. Ele dirige nossos passos quando consagramos nossos caminhos a Ele.', 'Senhor, entrego meu futuro nas Tuas mãos. Dirige meus passos. Amém.', 'Prepare uma reflexão sobre discernimento para compartilhar no encontro.', '{"O que significa \"consagrar\" seus planos ao Senhor?","O que você aprendeu sobre a vontade de Deus nestas semanas?"}', '2026-02-24 22:07:30.890938+00', '2026-05-13 12:53:51.627337+00', '9ae625cf-c913-4bf8-a059-37dbe1633dd6', 10, 'Entregando o futuro a Deus', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('dc10713e-090a-4fff-8a54-17b752ff1d16', NULL, 'Na casa de meu Pai há muitos aposentos. Vou preparar-lhes lugar. E quando eu for e lhes preparar lugar, voltarei e os levarei para mim.', 'João 14:2-3', 'Jesus prometeu voltar. Não é metáfora — é promessa real. Ele está preparando um lugar para nós. A eternidade com Cristo é o destino do cristão.', 'Jesus, obrigado pela promessa de um lar eterno. Minha esperança está em Ti. Amém.', 'Imagine como será estar na presença de Jesus para sempre. Escreva seus pensamentos.', '{"O que Jesus está preparando para nós?","Como a promessa da eternidade muda sua perspectiva?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 1, 'A promessa da eternidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('3f6aeb7a-90c5-462c-b213-108ce049d7d2', NULL, 'Assim será a ressurreição dos mortos. O corpo que é semeado é perecível, mas ressuscitará imperecível.', '1 Coríntios 15:42-44', 'A esperança cristã não é só espiritual — inclui a ressurreição do corpo. Teremos corpos glorificados, sem dor, doença ou morte.', 'Senhor, obrigado pela promessa de um corpo novo e glorificado. Minha esperança vai além desta vida. Amém.', 'Reflita: como a promessa da ressurreição te consola diante da fragilidade do corpo?', '{"O que a Bíblia ensina sobre a ressurreição do corpo?","Por que a ressurreição física é importante para a fé cristã?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 2, 'A ressurreição do corpo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('596afbea-0823-41b7-8212-cec83460ec91', NULL, 'Vi novos céus e nova terra. Ele enxugará dos seus olhos toda lágrima. Não haverá mais morte, nem tristeza, nem choro, nem dor.', 'Apocalipse 21:1-4', 'Deus não vai apenas consertar este mundo — vai criar um novo. Um mundo sem dor, morte ou pecado. Essa é a esperança que nos sustenta.', 'Senhor, anseio pelo dia em que não haverá mais lágrimas. Maranata! Amém.', 'Liste 3 coisas que deseja ver na nova criação e agradeça pela promessa.', '{"O que Apocalipse 21 revela sobre o futuro?","Como a esperança de \"nova criação\" nos consola hoje?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 3, 'Nova criação', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('d82505f5-984e-4ea4-a6c5-55228280dbdd', NULL, 'O Senhor mesmo descerá do céu, e os mortos em Cristo ressuscitarão primeiro. Depois, nós, os que estivermos vivos, seremos arrebatados.', '1 Tessalonicenses 4:16-17', 'Jesus voltará visível e gloriosamente. Os mortos em Cristo ressuscitarão e os vivos serão transformados. É a esperança central da fé cristã.', 'Jesus, vem! Espero ansiosamente por Teu retorno. Maranata! Amém.', 'Leia 1 Tessalonicenses 4:13-18 e medite na esperança que temos.', '{"O que acontecerá quando Jesus voltar?","Como a esperança da volta de Cristo afeta sua vida hoje?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 4, 'O retorno de Cristo', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('3ed46acf-81b8-42ec-b429-57bedf0af556', NULL, 'Pois os nossos sofrimentos leves e momentâneos estão produzindo para nós uma glória eterna que pesa mais do que todos eles.', '2 Coríntios 4:17-18', 'Quando olhamos para a eternidade, os sofrimentos presentes se tornam "leves e momentâneos". A perspectiva eterna transforma como vivemos o presente.', 'Senhor, ajuda-me a viver com olhos na eternidade, não apenas no temporal. Amém.', 'Diante de uma dificuldade atual, releia este verso e mude sua perspectiva.', '{"Como a perspectiva eterna muda nossa visão do sofrimento?","Você vive mais focado no temporal ou no eterno?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 5, 'Vivendo à luz da eternidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('efc96896-d560-45ba-8cad-6821343de53c', NULL, 'Acumulem para vocês tesouros nos céus. Pois onde estiver o seu tesouro, aí também estará o seu coração.', 'Mateus 6:19-21', 'Investir no que é eterno — fé, amor, serviço, relacionamentos — é a sabedoria suprema. O que fazemos para Deus ecoa na eternidade.', 'Senhor, ajuda-me a investir no que é eterno, não no que é passageiro. Amém.', 'Avalie: onde você está investindo mais — no temporal ou no eterno?', '{"O que são \"tesouros nos céus\"?","Como podemos investir na eternidade aqui e agora?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 6, 'Recompensas eternas', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('276913a5-a7e1-456e-a0b0-09a7f5b16696', NULL, 'Pois para mim o viver é Cristo e o morrer é lucro.', 'Filipenses 1:21-23', 'Para o cristão, a morte é uma passagem, não um beco sem saída. Paulo desejava estar com Cristo — e essa certeza remove o medo da morte.', 'Senhor, obrigado porque a morte não tem a última palavra. Em Ti, tenho vida eterna. Amém.', 'Reflita: a certeza da vida eterna remove seu medo da morte?', '{"Por que Paulo diz que \"morrer é lucro\"?","Como a esperança eterna nos liberta do medo da morte?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 7, 'A morte não é o fim', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('8ed82831-1c0c-4f30-8219-55e758f695b6', NULL, 'Que o Deus da esperança os encha de toda alegria e paz por crerem nEle, para que vocês transbordem de esperança, pelo poder do Espírito Santo.', 'Romanos 15:13', 'Esperança não é otimismo vago — é certeza baseada nas promessas de Deus. Essa esperança produz alegria e paz, mesmo em circunstâncias difíceis.', 'Deus da esperança, enche-me de alegria e paz. Que eu transborde de esperança pelo Espírito. Amém.', 'Compartilhe com alguém a esperança que você tem em Cristo.', '{"Qual a diferença entre esperança cristã e otimismo?","Como a esperança produz alegria e paz?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 8, 'Esperança que sustenta', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('030c2893-5290-4d81-89cb-8fe3a642590b', NULL, 'Portanto, vigiem, porque vocês não sabem o dia nem a hora.', 'Mateus 25:13', 'A volta de Cristo é certa, mas a data é desconhecida. Devemos viver prontos — não com medo, mas com expectativa alegre e vida fiel.', 'Jesus, quero estar pronto quando voltares. Ajuda-me a viver com fidelidade e expectativa. Amém.', 'Se Jesus voltasse hoje, o que você gostaria de ter feito diferente?', '{"O que significa \"vigiar\" esperando Cristo?","Você está vivendo pronto para a eternidade?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 9, 'Prontos para a eternidade', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('4154a604-1c0b-4dc3-a116-8a6bad437be0', NULL, 'Aquele que dá testemunho destas coisas diz: "Sim, venho em breve." Amém. Vem, Senhor Jesus!', 'Apocalipse 22:20-21', 'A Bíblia termina com uma oração de esperança: "Vem, Senhor Jesus!" Essa é a oração da Igreja em todos os tempos — e agora é a sua também.', 'Senhor Jesus, vem! Minha esperança está firmada em Ti. Maranata! Amém.', 'Prepare uma reflexão final sobre esperança cristã para compartilhar no encontro.', '{"O que significa a oração \"Maranata\"?","O que você aprendeu sobre eternidade e esperança nestas semanas?"}', '2026-02-24 22:08:03.196993+00', '2026-05-13 12:53:51.627337+00', '896052c1-3040-46cb-8515-236c7e2ce316', 10, 'Maranata: vem, Senhor Jesus!', NULL, '02f08580-80e5-4f57-8a2e-1b078d337278'),
('af72e9fc-4ffc-4ecc-9fe4-732e059f947e', NULL, '"Mas vocês", perguntou ele, "quem vocês dizem que eu sou?"', 'Mateus 16.15', 'Jesus fez essa pergunta aos discípulos depois de ouvir o que as pessoas falavam sobre Ele. Alguns diziam que Ele era profeta. Outros achavam que era João Batista. Havia muitas opiniões.
